var materialAdmin = angular.module("materialAdmin", [
    "ngStorage",
    "ngRoute",
    "ui.bootstrap",
    "pascalprecht.translate",
    "angular-loading-bar"
]);

(function() {

'use strict';

// Alias the loading bar for various backwards compatibilities since the project has matured:
angular.module('angular-loading-bar', ['cfp.loadingBarInterceptor']);
angular.module('chieffancypants.loadingBar', ['cfp.loadingBarInterceptor']);


/**
 * loadingBarInterceptor service
 *
 * Registers itself as an Angular interceptor and listens for XHR requests.
 */
angular.module('cfp.loadingBarInterceptor', ['cfp.loadingBar'])
  .config(['$httpProvider', function ($httpProvider) {
          
    var interceptor = ['$q', '$cacheFactory', '$timeout', '$rootScope', '$log', 'cfpLoadingBar', function ($q, $cacheFactory, $timeout, $rootScope, $log, cfpLoadingBar) {

      /**
       * The total number of requests made
       */
      var reqsTotal = 0;

      /**
       * The number of requests completed (either successfully or not)
       */
      var reqsCompleted = 0;

      /**
       * The amount of time spent fetching before showing the loading bar
       */
      var latencyThreshold = cfpLoadingBar.latencyThreshold;

      /**
       * $timeout handle for latencyThreshold
       */
      var startTimeout;


      /**
       * calls cfpLoadingBar.complete() which removes the
       * loading bar from the DOM.
       */
      function setComplete() {
        $timeout.cancel(startTimeout);
        cfpLoadingBar.complete();
        reqsCompleted = 0;
        reqsTotal = 0;
      }

      /**
       * Determine if the response has already been cached
       * @param  {Object}  config the config option from the request
       * @return {Boolean} retrns true if cached, otherwise false
       */
      function isCached(config) {
        var cache;
        var defaultCache = $cacheFactory.get('$http');
        var defaults = $httpProvider.defaults;

        // Choose the proper cache source. Borrowed from angular: $http service
        if ((config.cache || defaults.cache) && config.cache !== false &&
          (config.method === 'GET' || config.method === 'JSONP')) {
            cache = angular.isObject(config.cache) ? config.cache
              : angular.isObject(defaults.cache) ? defaults.cache
              : defaultCache;
        }

        var cached = cache !== undefined ?
          cache.get(config.url) !== undefined : false;

        if (config.cached !== undefined && cached !== config.cached) {
          return config.cached;
        }
        config.cached = cached;
        return cached;
      }


      return {
        'request': function(config) {
            
          // Check to make sure this request hasn't already been cached and that
          // the requester didn't explicitly ask us to ignore this request:
          if (!config.ignoreLoadingBar && !isCached(config)) {
            $rootScope.$broadcast('cfpLoadingBar:loading', {url: config.url});
            if (reqsTotal === 0) {
              startTimeout = $timeout(function() {
                cfpLoadingBar.start();
              }, latencyThreshold);
            }
            reqsTotal++;
            cfpLoadingBar.set(reqsCompleted / reqsTotal);
          }
          return config;
        },

        'response': function(response) {
          if (!response || !response.config) {
            $log.error('Broken interceptor detected: Config object not supplied in response:\n https://github.com/chieffancypants/angular-loading-bar/pull/50');
            return response;
          }

          if (!response.config.ignoreLoadingBar && !isCached(response.config)) {
            reqsCompleted++;
            $rootScope.$broadcast('cfpLoadingBar:loaded', {url: response.config.url, result: response});
            if (reqsCompleted >= reqsTotal) {
              setComplete();
            } else {
              cfpLoadingBar.set(reqsCompleted / reqsTotal);
            }
          }
          return response;
        },

        'responseError': function(rejection) {
          if (!rejection || !rejection.config) {
            $log.error('Broken interceptor detected: Config object not supplied in rejection:\n https://github.com/chieffancypants/angular-loading-bar/pull/50');
            return $q.reject(rejection);
          }

          if (!rejection.config.ignoreLoadingBar && !isCached(rejection.config)) {
            reqsCompleted++;
            $rootScope.$broadcast('cfpLoadingBar:loaded', {url: rejection.config.url, result: rejection});
            if (reqsCompleted >= reqsTotal) {
              setComplete();
            } else {
              cfpLoadingBar.set(reqsCompleted / reqsTotal);
            }
          }
          return $q.reject(rejection);
        }
      };
    }];

    $httpProvider.interceptors.push(interceptor);
  }]);


/**
 * Loading Bar
 *
 * This service handles adding and removing the actual element in the DOM.
 * Generally, best practices for DOM manipulation is to take place in a
 * directive, but because the element itself is injected in the DOM only upon
 * XHR requests, and it's likely needed on every view, the best option is to
 * use a service.
 */
angular.module('cfp.loadingBar', [])
  .provider('cfpLoadingBar', function() {

    this.autoIncrement = true;
    this.includeSpinner = true;
    this.includeBar = true;
    this.latencyThreshold = 100;
    this.startSize = 0.02;
    this.parentSelector = 'body';
    this.spinnerTemplate = '<div id="loading-bar-spinner"><div class="spinner-icon"></div></div>';
    this.loadingBarTemplate = '<div id="loading-bar"><div class="bar"><div class="peg"></div></div></div>';

    this.$get = ['$injector', '$document', '$timeout', '$rootScope', function ($injector, $document, $timeout, $rootScope) {
      var $animate;
      var $parentSelector = this.parentSelector,
        loadingBarContainer = angular.element(this.loadingBarTemplate),
        loadingBar = loadingBarContainer.find('div').eq(0),
        spinner = angular.element(this.spinnerTemplate);

      var incTimeout,
        completeTimeout,
        started = false,
        status = 0;

      var autoIncrement = this.autoIncrement;
      var includeSpinner = this.includeSpinner;
      var includeBar = this.includeBar;
      var startSize = this.startSize;

      /**
       * Inserts the loading bar element into the dom, and sets it to 2%
       */
      function _start() {
        if (!$animate) {
          $animate = $injector.get('$animate');
        }

        var $parent = $document.find($parentSelector).eq(0);
        $timeout.cancel(completeTimeout);

        // do not continually broadcast the started event:
        if (started) {
          return;
        }

        $rootScope.$broadcast('cfpLoadingBar:started');
        started = true;

        if (includeBar) {
          $animate.enter(loadingBarContainer, $parent, angular.element($parent[0].lastChild));
        }

        if (includeSpinner) {
          $animate.enter(spinner, $parent, angular.element($parent[0].lastChild));
        }

        _set(startSize);
      }

      /**
       * Set the loading bar's width to a certain percent.
       *
       * @param n any value between 0 and 1
       */
      function _set(n) {
        if (!started) {
          return;
        }
        var pct = (n * 100) + '%';
        loadingBar.css('width', pct);
        status = n;

        // increment loadingbar to give the illusion that there is always
        // progress but make sure to cancel the previous timeouts so we don't
        // have multiple incs running at the same time.
        if (autoIncrement) {
          $timeout.cancel(incTimeout);
          incTimeout = $timeout(function() {
            _inc();
          }, 250);
        }
      }

      /**
       * Increments the loading bar by a random amount
       * but slows down as it progresses
       */
      function _inc() {
        if (_status() >= 1) {
          return;
        }

        var rnd = 0;

        // TODO: do this mathmatically instead of through conditions

        var stat = _status();
        if (stat >= 0 && stat < 0.25) {
          // Start out between 3 - 6% increments
          rnd = (Math.random() * (5 - 3 + 1) + 3) / 100;
        } else if (stat >= 0.25 && stat < 0.65) {
          // increment between 0 - 3%
          rnd = (Math.random() * 3) / 100;
        } else if (stat >= 0.65 && stat < 0.9) {
          // increment between 0 - 2%
          rnd = (Math.random() * 2) / 100;
        } else if (stat >= 0.9 && stat < 0.99) {
          // finally, increment it .5 %
          rnd = 0.005;
        } else {
          // after 99%, don't increment:
          rnd = 0;
        }

        var pct = _status() + rnd;
        _set(pct);
      }

      function _status() {
        return status;
      }

      function _completeAnimation() {
        status = 0;
        started = false;
      }

      function _complete() {
        if (!$animate) {
          $animate = $injector.get('$animate');
        }

        $rootScope.$broadcast('cfpLoadingBar:completed');
        _set(1);

        $timeout.cancel(completeTimeout);

        // Attempt to aggregate any start/complete calls within 500ms:
        completeTimeout = $timeout(function() {
          var promise = $animate.leave(loadingBarContainer, _completeAnimation);
          if (promise && promise.then) {
            promise.then(_completeAnimation);
          }
          $animate.leave(spinner);
        }, 500);
      }

      return {
        start            : _start,
        set              : _set,
        status           : _status,
        inc              : _inc,
        complete         : _complete,
        autoIncrement    : this.autoIncrement,
        includeSpinner   : this.includeSpinner,
        latencyThreshold : this.latencyThreshold,
        parentSelector   : this.parentSelector,
        startSize        : this.startSize
      };


    }];     //
  });       // wtf javascript. srsly
})();       //
;

materialAdmin.controller("BancoArquivoController", [
    "$scope",
    "$http",
    "$q",
    "FileService",

    function ($scope, $http, $q, FileService) {

        // ==========================================================
        // DADOS
        // ==========================================================

        $scope.registros = [];
        $scope.departamentosFiltragem = [];
        $scope.originsFiltro = [];

        $scope.breadcrumb = [];

        $scope.loading = false;
        $scope.modoExibicao = "GRADE";

        $scope.filtro = {
            nome: "",
            departamentoId: "",
            origem: ""
        };

        $scope.showTutorial = false;
        $scope.hasTutorial = false;

        $scope.usuario = null;


        // ==========================================================
        // USUÁRIO / PERMISSÕES
        // ==========================================================

        function carregarUsuario() {

            try {

                var usuarioStorage =
                    sessionStorage.getItem("usuario");

                if (usuarioStorage) {
                    $scope.usuario =
                        JSON.parse(usuarioStorage);
                }

            } catch (e) {

                console.error(
                    "Erro ao carregar usuário:",
                    e
                );

                $scope.usuario = null;
            }
        }


        function obterScopeUsuario() {

            if (!$scope.usuario) {
                return "";
            }

            return (
                $scope.usuario.scope ||
                $scope.usuario.scopo ||
                $scope.usuario.perfil ||
                $scope.usuario.role ||
                ""
            )
            .toString()
            .toLowerCase();
        }


        $scope.isAdministrador = false;
        $scope.isAtendente = false;
        $scope.isRevendedor = false;


        function verificarPermissoes() {

            var scope =
                obterScopeUsuario();

            $scope.isAdministrador =
                scope === "administrador" ||
                scope === "admin";

            $scope.isAtendente =
                scope === "atendente";

            $scope.isRevendedor =
                scope === "revendedor";
        }


        // ==========================================================
        // ACESSO AO BANCO
        // ==========================================================

        $scope.podeAcessarBancoArquivos =
            function () {

                return (
                    $scope.isAdministrador ||
                    $scope.isAtendente ||
                    $scope.isRevendedor
                );

            };


        // ==========================================================
        // INIT
        // ==========================================================

        $scope.onInit = function () {

            carregarUsuario();

            verificarPermissoes();

            $scope.getAll(false);

        };


        // ==========================================================
        // LISTAR ARQUIVOS
        // ==========================================================

        $scope.getAll = function (mais) {

            $scope.loading = true;

            /*
             * IMPORTANTE:
             *
             * O FileService que você mandou só possui:
             *
             * upload()
             * remover()
             *
             * Ele ainda não possui uma função para LISTAR
             * os arquivos.
             *
             * Por isso não vou inventar um endpoint aqui.
             */

            var url =
                $setting.api +
                "/api/upload";

            var params = {
                nome:
                    $scope.filtro.nome || "",

                departamentoId:
                    $scope.filtro.departamentoId || "",

                origem:
                    $scope.filtro.origem || ""
            };


            $http.get(
                url,
                {
                    params: params
                }
            )
            .then(function (response) {

                var dados =
                    response.data;

                if (angular.isArray(dados)) {

                    $scope.registros =
                        dados;

                } else if (
                    dados &&
                    angular.isArray(dados.registros)
                ) {

                    $scope.registros =
                        dados.registros;

                } else if (
                    dados &&
                    angular.isArray(dados.arquivos)
                ) {

                    $scope.registros =
                        dados.arquivos;

                } else {

                    $scope.registros = [];
                }


                montarFiltros();

            })
            .catch(function (error) {

                console.error(
                    "Erro ao carregar banco de arquivos:",
                    error
                );

                $scope.registros = [];

            })
            .finally(function () {

                $scope.loading = false;

            });

        };


        // ==========================================================
        // FILTROS
        // ==========================================================

        function montarFiltros() {

            var departamentos = {};
            var origens = {};

            angular.forEach(
                $scope.registros,
                function (registro) {

                    if (
                        registro.departamentoId !== undefined &&
                        registro.departamentoId !== null
                    ) {

                        departamentos[
                            registro.departamentoId
                        ] =
                            registro.departamentoNome ||
                            registro.departamento ||
                            registro.departamentoId;

                    }


                    if (registro.origem) {

                        origens[
                            registro.origem
                        ] = registro.origem;

                    }

                }
            );


            $scope.departamentosFiltragem = [];

            angular.forEach(
                departamentos,
                function (nome, id) {

                    $scope.departamentosFiltragem.push({
                        id: id,
                        nome: nome
                    });

                }
            );


            $scope.originsFiltro = [];

            angular.forEach(
                origens,
                function (nome) {

                    $scope.originsFiltro.push(
                        nome
                    );

                }
            );

        }


        // ==========================================================
        // SELEÇÃO
        // ==========================================================

        $scope.temSelecionados =
            function () {

                return $scope.registros.some(
                    function (registro) {

                        return registro.selecionado === true;

                    }
                );

            };


        $scope.disabledDeleteSelecionados =
            function () {

                return !$scope.temSelecionados();

            };


        // ==========================================================
        // REMOVER ARQUIVO
        // ==========================================================

        $scope.onDelete =
            function (registro) {

                if (!registro) {
                    return;
                }


                if (
                    !confirm(
                        "Deseja realmente remover este arquivo?"
                    )
                ) {
                    return;
                }


                var arquivo =
                    registro.fileName ||
                    registro.filename ||
                    registro.nome ||
                    registro.arquivo ||
                    registro.path;


                if (!arquivo) {

                    alert(
                        "Não foi possível identificar o arquivo."
                    );

                    return;

                }


                $scope.loading = true;


                FileService.remover(
                    arquivo
                )
                .then(function () {

                    var index =
                        $scope.registros.indexOf(
                            registro
                        );

                    if (index !== -1) {

                        $scope.registros.splice(
                            index,
                            1
                        );

                    }

                })
                .catch(function (error) {

                    console.error(
                        "Erro ao remover arquivo:",
                        error
                    );

                    alert(
                        "Não foi possível remover o arquivo."
                    );

                })
                .finally(function () {

                    $scope.loading = false;

                });

            };


        // ==========================================================
        // REMOVER SELECIONADOS
        // ==========================================================

        $scope.onDeleteSelecionados =
            function () {

                var selecionados =
                    $scope.registros.filter(
                        function (registro) {

                            return registro.selecionado === true;

                        }
                    );


                if (!selecionados.length) {
                    return;
                }


                if (
                    !confirm(
                        "Deseja realmente remover os arquivos selecionados?"
                    )
                ) {
                    return;
                }


                $scope.loading = true;


                var promessas = [];


                angular.forEach(
                    selecionados,
                    function (registro) {

                        var arquivo =
                            registro.fileName ||
                            registro.filename ||
                            registro.nome ||
                            registro.arquivo ||
                            registro.path;


                        if (arquivo) {

                            promessas.push(
                                FileService.remover(
                                    arquivo
                                )
                            );

                        }

                    }
                );


                $q.all(promessas)
                    .then(function () {

                        $scope.registros =
                            $scope.registros.filter(
                                function (registro) {

                                    return (
                                        registro.selecionado !== true
                                    );

                                }
                            );

                    })
                    .catch(function (error) {

                        console.error(
                            "Erro ao remover arquivos:",
                            error
                        );

                        alert(
                            "Ocorreu um erro ao remover os arquivos."
                        );

                    })
                    .finally(function () {

                        $scope.loading = false;

                    });

            };


        // ==========================================================
        // UPLOAD
        // ==========================================================

        $scope.enviarArquivo =
            function (
                arquivo,
                dados
            ) {

                if (!arquivo) {

                    alert(
                        "Selecione um arquivo."
                    );

                    return;

                }


                $scope.loading = true;


                FileService.upload(
                    arquivo,
                    dados || {}
                )
                .then(function (response) {




                    /*
                     * Se a API devolver o registro criado,
                     * adicionamos imediatamente na tela.
                     */

                    var registro =
                        response.data;


                    if (
                        registro &&
                        registro.arquivo
                    ) {

                        $scope.registros.unshift(
                            registro
                        );

                    } else {

                        // Recarrega a lista
                        $scope.getAll(false);

                    }

                })
                .catch(function (error) {

                    console.error(
                        "Erro no upload:",
                        error
                    );

                    alert(
                        "Não foi possível enviar o arquivo."
                    );

                })
                .finally(function () {

                    $scope.loading = false;

                });

            };


        // ==========================================================
        // INPUT FILE
        // ==========================================================

        $scope.onArquivoSelecionado =
            function (
                element,
                dados
            ) {

                if (
                    !element ||
                    !element.files ||
                    !element.files.length
                ) {
                    return;
                }


                var arquivo =
                    element.files[0];


                $scope.enviarArquivo(
                    arquivo,
                    dados
                );

            };


        // ==========================================================
        // MODO DE EXIBIÇÃO
        // ==========================================================

        $scope.alterarModoExibicao =
            function (modo) {

                if (
                    modo !== "GRADE" &&
                    modo !== "LISTA"
                ) {
                    return;
                }

                $scope.modoExibicao =
                    modo;

            };


        // ==========================================================
        // BREADCRUMB
        // ==========================================================

        $scope.clickBreadCrumb =
            function (item, index) {

                if (
                    !$scope.breadcrumb ||
                    !$scope.breadcrumb.length
                ) {
                    return;
                }


                $scope.breadcrumb =
                    $scope.breadcrumb.slice(
                        0,
                        index + 1
                    );


                $scope.getAll(false);

            };


        // ==========================================================
        // NOVO ARQUIVO
        // ==========================================================

        $scope.onMostrarModalNovoArquivo =
            function () {

                $scope.mostrarModalNovoArquivo = true;

            };


        // ==========================================================
        // NOVA PASTA
        // ==========================================================

        $scope.abrirModalNovaPasta =
            function () {

                $scope.mostrarModalNovaPasta = true;

            };


        // ==========================================================
        // MOVER PARA
        // ==========================================================

        $scope.onMostrarModalMoverPara =
            function (registro) {

                $scope.registroMover =
                    registro;

                $scope.mostrarModalMoverPara =
                    true;

            };


        // ==========================================================
        // EDITAR
        // ==========================================================

        $scope.onEditar =
            function (registro) {

                $scope.registroEditando =
                    registro;

            };


        // ==========================================================
        // IMAGEM DO ARQUIVO
        // ==========================================================

        $scope.getBackgroundImageUrl =
            function (registro) {

                if (!registro) {
                    return "";
                }


                if (
                    registro.thumbnail
                ) {
                    return registro.thumbnail;
                }


                if (
                    registro.url
                ) {
                    return registro.url;
                }


                if (
                    registro.fileUrl
                ) {
                    return registro.fileUrl;
                }


                return "";

            };


        // ==========================================================
        // MAIS ARQUIVOS
        // ==========================================================

        $scope.showMore =
            function () {

                $scope.getAll(true);

            };


        // ==========================================================
        // TUTORIAL
        // ==========================================================

        $scope.fecharTutorial =
            function () {

                $scope.showTutorial =
                    false;

            };


        // ==========================================================
        // INICIALIZA
        // ==========================================================

        $scope.onInit();

    }
]);





/* ========================================= */
/* ROTAS                                     */
/* ========================================= */

materialAdmin.service("ChatService", ChatService);


    ChatService.$inject = [
        "$http",
        "$q",
    ];


    function ChatService(
        $http,
        $q,
    ) {

        var service = {};


        // ==========================================
        // MÉTODOS PÚBLICOS
        // ==========================================

        service.buscarChats = buscarChats;
        service.buscarChat = buscarChat;
        service.enviarMensagem = enviarMensagem;
        service.buscarStatus = buscarStatus;
        service.buscarQR = buscarQR;
        service.buscarContatos = buscarContatos;


        return service;


        // ==========================================
        // HEADERS
        // ==========================================

        function headers() {

            var token =
                localStorage.getItem("token");


            var h = {

                "Accept":
                    "application/json",

                "ngrok-skip-browser-warning":
                    "true"
            };


            if (token) {

                h.Authorization =
                    "Bearer " + token;
            }


            return h;
        }


        // ==========================================
        // BUSCAR TODOS OS CHATS
        // GET /chats
        // ==========================================

        function buscarChats() {

            return $http({

                method: "GET",

                url:
                    "https://socket.n3bot.com.br/chats",

                cache: false,

                headers:
                    headers()

            });

        }


        // ==========================================
        // BUSCAR UM CHAT
        // GET /chat/:numero
        // ==========================================

        function buscarChat(numero) {

            return $http({

                method: "GET",

                url:

                    "https://socket.n3bot.com.br/chat/" +
                    encodeURIComponent(numero),

                cache: false,

                headers:
                    headers()

            });

        }


        // ==========================================
        // ENVIAR MENSAGEM
        // POST /send
        // ==========================================

        function enviarMensagem(
            numero,
            mensagem,
            remetente
        ) {

            return $http({

                method: "POST",

                url:

                    "https://socket.n3bot.com.br/send",

                cache: false,

                headers: {

                    "Content-Type":
                        "application/json",

                    "Accept":
                        "application/json",

                    "ngrok-skip-browser-warning":
                        "true"
                },

                data: {

                    numero: numero,

                    mensagem: mensagem,

                    remetente:
                        remetente ||
                        "gestor"
                }

            });

        }


        // ==========================================
        // STATUS WHATSAPP
        // GET /status
        // ==========================================

        function buscarStatus() {

            return $http({

                method: "GET",

                url:

                    "https://socket.n3bot.com.br/status",

                cache: false,

                headers:
                    headers()

            });

        }


        // ==========================================
        // QR CODE
        // GET /qr
        // ==========================================

        function buscarQR() {

            return $http({

                method: "GET",

                url:

                    "https://socket.n3bot.com.br/qr",

                cache: false,

                headers:
                    headers()

            });

        }


        // ==========================================
        // CONTATOS
        // GET /chats
        // ==========================================

        function buscarContatos() {

            return $http({

                method: "GET",

                url:
                    "https://socket.n3bot.com.br/chats",

                cache: false,

                headers:
                    headers()

            });

        }

    }

    materialAdmin.service("SocketService", SocketService);

    SocketService.$inject = [
        "$rootScope",

    ];

    function SocketService($rootScope, ) {

        var service = {};

        var socket = null;

        var listeners = [];

        service.connect = connect;
        service.disconnect = disconnect;
        service.send = send;
        service.on = on;
        service.getSocket = getSocket;
        service.isConnected = isConnected;

        return service;

        // ==========================
        // CONECTAR
        // ==========================
        function connect() {

            if (socket && socket.readyState === WebSocket.OPEN) {
                return;
            }

            var wsUrl = CONFIG.API
                .replace("https://socket.n3bot.com.br", "wss://socket.n3bot.com.br")

            socket = new WebSocket(wsUrl);

            socket.onopen = function () {



                $rootScope.$applyAsync();

            };

socket.onmessage = function (event) {



    try {

        var data = JSON.parse(event.data);

        listeners.forEach(function (callback) {

            $rootScope.$applyAsync(function () {

                callback(data);

            });

        });

    } catch (e) {

        console.error("Erro WebSocket:", e);

    }

};

            socket.onerror = function (e) {

                console.error("Erro WebSocket", e);

            };

            socket.onclose = function () {

                console.warn("WebSocket desconectado.");

                setTimeout(function () {

                    connect();

                }, 3000);

            };

        }

        // ==========================
        // DESCONECTAR
        // ==========================
        function disconnect() {

            if (socket) {

                socket.close();

                socket = null;

            }

        }

        // ==========================
        // ENVIAR
        // ==========================
        function send(obj) {

            if (!socket) {

                connect();

            }

            if (socket.readyState !== WebSocket.OPEN) {

                console.warn("Socket ainda não conectado.");

                return;

            }

            socket.send(

                JSON.stringify(obj)

            );

        }

        // ==========================
        // EVENTOS
        // ==========================
        function on(callback) {

            listeners.push(callback);

        }

        // ==========================
        // SOCKET
        // ==========================
        function getSocket() {

            return socket;

        }

        // ==========================
        // STATUS
        // ==========================
        function isConnected() {

            return socket &&
                socket.readyState === WebSocket.OPEN;

        }

    }

materialAdmin.controller("DashboardController", DashboardController);


DashboardController.$inject = [
    "$scope",
    "$interval",
    "$timeout",
    "$window",
    "ChatService"
];


function DashboardController(
    $scope,
    $interval,
    $timeout,
    $window,
    ChatService
) {
        var vm = this;


        // ==========================================
        // VARIÁVEIS
        // ==========================================

        vm.chats = [];

        vm.atendentes = [];

        vm.filtroAtendente = "";

        vm.filtroTabela = "";

        vm.filtroStatus = "";

        vm.aba = "ativos";

        vm.carregando = false;

        vm.erro = null;

        vm.chatSelecionado = null;


        // ==========================================
        // CONTADORES
        // ==========================================

        vm.contadores = {
            ativos: 1,
            pendentes: 0
        };


        // ==========================================
        // ESTATÍSTICAS
        // ==========================================

        vm.estatisticas = {

            atendentesOnline: 0,

            potenciais: 0,

            novasMensagens: 0,

            ticketActive: 0,

            ticketPending: 0,

            retornos: 0

        };


        // ==========================================
        // INICIAIS
        // ==========================================

        vm.iniciais = function (nome) {

            if (!nome) {
                return "N3";
            }

            var partes = String(nome)
                .trim()
                .split(/\s+/);


            if (partes.length === 1) {

                return partes[0]
                    .substring(0, 2)
                    .toUpperCase();

            }


            return (
                partes[0].charAt(0) +
                partes[partes.length - 1].charAt(0)
            ).toUpperCase();

        };


        // ==========================================
        // ÚLTIMA MENSAGEM
        // ==========================================

        vm.ultimaMensagem = function (chat) {

            if (
                !chat ||
                !chat.mensagens ||
                !chat.mensagens.length
            ) {

                return "";

            }


            var msg =
                chat.mensagens[
                    chat.mensagens.length - 1
                ];


            return (
                msg.texto ||
                msg.mensagem ||
                msg.message ||
                msg.body ||
                ""
            );

        };


        // ==========================================
        // NORMALIZAR CHAT
        // ==========================================

        function normalizarChat(chat) {

            chat = chat || {};

            chat.cliente =
                chat.cliente || {};


            chat.numero = String(
                chat.numero ||
                chat.phone ||
                chat.telefone ||
                chat.from ||
                chat.id ||
                ""
            );


            chat.nome =
                chat.nome ||
                chat.cliente.nome ||
                chat.name ||
                chat.numero;


            chat.mensagens =
                chat.mensagens ||
                chat.messages ||
                [];


            if (!Array.isArray(chat.mensagens)) {
                chat.mensagens = [];
            }


            chat.novas = Number(
                chat.novas ||
                chat.novasMensagens ||
                chat.unread ||
                0
            );


            return chat;

        }


        // ==========================================
        // CARREGAR CHATS
        // ==========================================

        vm.carregarChats = function () {

            ChatService.buscarChats()

                .then(function (response) {

                    var data =
                        response.data || {};


                    var lista;


                    if (Array.isArray(data)) {

                        lista = data;

                    } else {

                        lista =
                            data.chats ||
                            data.data ||
                            data.contatos ||
                            [];

                    }


                    if (!Array.isArray(lista)) {
                        lista = [];
                    }


                    vm.chats =
                        lista.map(normalizarChat);


                    // ==================================
                    // ATIVOS
                    // ==================================

                    vm.contadores.ativos =
                        vm.chats.filter(function (chat) {

                            return (
                                chat.ticket_active === true ||
                                chat.ticket_active === 1 ||
                                chat.ticketActive === true ||
                                chat.status === "active" ||
                                chat.status === "ativo"
                            );

                        }).length;


                    // ==================================
                    // PENDENTES
                    // ==================================

                    vm.contadores.pendentes =
                        vm.chats.filter(function (chat) {

                            return (
                                chat.ticket_pending === true ||
                                chat.ticket_pending === 1 ||
                                chat.ticketPending === true ||
                                chat.status === "pending" ||
                                chat.status === "pendente"
                            );

                        }).length;


                    // ==================================
                    // NOVAS MENSAGENS
                    // ==================================

                    vm.estatisticas.novasMensagens =
                        vm.chats.reduce(function (
                            total,
                            chat
                        ) {

                            return total +
                                Number(chat.novas || 0);

                        }, 0);


                    // ==================================
                    // TICKETS
                    // ==================================

                    vm.estatisticas.ticketActive =
                        vm.contadores.ativos;


                    vm.estatisticas.ticketPending =
                        vm.contadores.pendentes;


                    // ==================================
                    // RETORNOS
                    // ==================================

                    vm.estatisticas.retornos =
                        vm.chats.reduce(function (
                            total,
                            chat
                        ) {

                            return total +
                                Number(
                                    chat.retornos || 0
                                );

                        }, 0);


                })

                .catch(function (error) {


                    vm.erro =
                        "Não foi possível carregar os chats.";

                });

        };


        // ==========================================
        // CARREGAR STATUS
        // ==========================================

        vm.carregarStatus = function () {

            ChatService.buscarStatus()

                .then(function (response) {



                    var data =
                        response.data || {};


                    // ==================================
                    // ATENDENTES
                    // ==================================

                    var lista =
                        Array.isArray(data.atendentes)
                            ? data.atendentes
                            : [];


                    vm.atendentes =
                        lista.map(function (atendente) {

                            atendente =
                                atendente || {};


                            /*
                             * SUA API RETORNA:
                             *
                             * status: "online"
                             *
                             * O HTML USA:
                             *
                             * atendente.online
                             *
                             * Então convertemos aqui.
                             */

                            atendente.online =
                                String(
                                    atendente.status || ""
                                ).toLowerCase() === "online";


                            atendente.nome =
                                atendente.nome ||
                                "Atendente";


                            atendente.novas =
                                Number(
                                    atendente.novas ||
                                    atendente.novasMensagens ||
                                    0
                                );


                            atendente.ticketActive =
                                Number(
                                    atendente.ticketActive ||
                                    atendente.ticket_active ||
                                    0
                                );


                            atendente.ticketPending =
                                Number(
                                    atendente.ticketPending ||
                                    atendente.ticket_pending ||
                                    0
                                );


                            atendente.retornos =
                                Number(
                                    atendente.retornos || 0
                                );


                            return atendente;

                        });


                    // ==================================
                    // CONTAR ONLINE
                    // ==================================

                    vm.estatisticas.atendentesOnline =
                        vm.atendentes.filter(
                            function (atendente) {

                                return (
                                    atendente.online === true
                                );

                            }
                        ).length;



                    // ==================================
                    // POTENCIAIS
                    // ==================================

                    vm.estatisticas.potenciais =
                        Number(
                            data.potenciais || 0
                        );


                })

                .catch(function (error) {




                    vm.atendentes = [];

                    vm.estatisticas.atendentesOnline = 0;

                });

        };


        // ==========================================
        // FILTRO DE STATUS
        // ==========================================

        vm.filtroFuncStatus = function (atendente) {

            if (!vm.filtroStatus) {
                return true;
            }


            return atendente.online ===
                (
                    vm.filtroStatus === "online"
                );

        };


        // ==========================================
        // SELECIONAR ATENDENTE
        // ==========================================

        vm.selecionarAtendente = function (atendente) {

            if (!atendente) {
                return;
            }


            vm.atendenteSelecionado =
                atendente;

        };


        // ==========================================
        // ABRIR CHAT
        // ==========================================

        vm.abrirChat = function (chat) {

            if (!chat || !chat.numero) {
                return;
            }


            vm.chatSelecionado = chat;


            $window.location.href =
                "chat.html?numero=" +
                encodeURIComponent(
                    chat.numero
                );

        };


        // ==========================================
        // QR CODE
        // ==========================================

        vm.abrirQR = function () {

            $window.location.href =
                "qr.html";

        };


        // ==========================================
        // CONFIGURAÇÕES
        // ==========================================

        vm.configuracoes = function () {

        };


        // ==========================================
        // CARREGAR TUDO
        // ==========================================

        vm.carregarTudo = function () {

            vm.carregando = true;

            vm.erro = null;


            vm.carregarChats();

            vm.carregarStatus();


            $timeout(function () {

                vm.carregando = false;

            }, 500);

        };


        // ==========================================
        // INICIALIZAÇÃO
        // ==========================================

        vm.carregarTudo();


        // ==========================================
        // ATUALIZAÇÃO AUTOMÁTICA
        // ==========================================

        $interval(
            function () {

                vm.carregarChats();

                vm.carregarStatus();

            },
            5000
        );

    }

materialAdmin.controller("FeaturesAiController", [
    "$scope",
    "$uibModal",
    "FeaturesAiService",
    "AiTemplateService",
    "DepartamentoService",
    "ClienteService",
    "$location",
    "$route",

    function (
        $scope,
        $uibModal,
        FeaturesAiService,
        AiTemplateService,
        DepartamentoService,
        ClienteService,
        $location,
        $route
    )  {

        $scope.filtro = {
            id: "",
            name: "",
            category: "ALL",
            resellerId: "",
            clientId: "",
            status: "ALL",
            offset: 0
        };

        $scope.showClients =
            


        $scope.limit = 20;
        $scope.totalItems = 0;
        $scope.showMore = true;

        $scope.onInit = function () {
            $scope.getFeature();
        };

        $scope.getFeature = function () {

            $scope.filtro.resellerId =
                $scope.filtro.reseller ?
                $scope.filtro.reseller.id :
                $scope.filtro.resellerId;

            $scope.filtro.clientId =
                $scope.filtro.client ?
                $scope.filtro.client.id :
                $scope.filtro.clientId;

            FeaturesAiService.getAll($scope.filtro)
                .then(function (response) {

                    $scope.partners = response.data;
                    $scope.totalItems = $scope.partners.length;

                })
                .catch(function (error) {
                    console.error(
                        "Erro ao buscar funcionalidades:",
                        error
                    );
                });
        };


        // ==========================================
        // IR PARA MODELOS
        // ==========================================

        $scope.linkDepartment = function (id) {

            $location.path(
                "/ia-integrations/mode/" + id
            );

        };


        // ==========================================
        // RECUPERAR DEPARTAMENTOS
        // ==========================================

        $scope.recoverDepartmentsAdjust = function () {

            var id = $route.current.params.id;

            if (!id) {
                console.error("ID da funcionalidade não informado");
                return;
            }

            FeaturesAiService.getByIdManager(id)
                .then(function (response) {

                    $scope.feature = response.data;

                    DepartamentoService.getAtivos()
                        .then(function (response) {

                            $scope.departamentos =
                                response.data.map(function (department) {

                                    return {
                                        id: department.id,
                                        name: department.nome,
                                        selected: false
                                    };

                                });

                            $scope.ajustDepartmanent();

                        });

                })
                .catch(function (error) {

                    console.error(
                        "Erro ao buscar funcionalidade:",
                        error
                    );

                });
        };


        // ==========================================
        // VOLTAR
        // ==========================================

        $scope.voltar = function () {
            $location.path("/ia-integrations/home");
        };


        // ==========================================
        // SALVAR
        // ==========================================

        $scope.updateManagerFeature = function () {

            var id = $route.current.params.id;

            var originalIds =
                ($scope.feature.departments || [])
                .map(function (dep) {
                    return dep.id;
                });

            var data =
                $scope.departamentos
                .filter(function (department) {

                    var wasSelected =
                        originalIds.indexOf(department.id) !== -1;

                    return department.selected !== wasSelected;

                })
                .map(function (department) {

                    return {
                        confDepartmentId: department.id,
                        promptFeatureId: id,
                        active: department.selected
                    };

                });

            if (data.length === 0) {

                swal(
                    "Nenhuma alteração",
                    "Nenhuma modificação foi detectada nos departamentos.",
                    "info"
                );

                return;
            }

            FeaturesAiService.updateManagerFeature(data)
                .then(function () {

                    $location.path(
                        "/ia-integrations/home"
                    );

                })
                .catch(function (error) {

                    swal({
                        title: "Erro!",
                        text: "Erro ao tentar atualizar informação",
                        details: error.data.message,
                        type: "error"
                    });

                });
        };

    }
]);

