materialAdmin.controller('MenuAiController', function ($scope, $translate, $uibModal, $http, MenuAiService, $timeout, FeaturesAiService, FileService, ClienteService) {
    $scope.filtro = {
        name: "",
        featureId: "0",
        offset: 0,
        clientId: null
    }

    $scope.limit = 20;

    $scope.totalItems = 0;

    $scope.menuList = [];

    $scope.features = [];

    $scope.initialConfig = {};

    $scope.showClients = []

    $scope.onInit = function () {
        $scope.getMenus();

        if ($scope.features.length == 0) {
            FeaturesAiService.getSimple().then(function (response) {
                $scope.features = response.data;
            });
        }

        $http.get('views/smbot/ai-integrations/menus/icons-zmdi.json')
            .then(function (response) {
                $scope.zmdiIcons = response.data;
            });
    };

    $scope.$watch('function.client', function (newVal, oldVal) {
        if (!newVal?.id) return;

        FeaturesAiService.getSimple(newVal.id).then(function (response) {
            $scope.features = response.data;
        });
    });

    $scope.nextPage = function () {
        $scope.filtro.offset += $scope.limit;
        $scope.getMenus(true);
    };

    $scope.getMenus = function (forMore) {
        $scope.filtro.clientId = $scope.filtro.client?.id || $scope.filtro.clientId;

        if (!forMore) {
            $scope.filtro.offset = 0;
        }

        MenuAiService.getAll($scope.filtro).then(function (response) {

            if (forMore) {
                $scope.menuList = [...$scope.menuList, ...response.data].reduce((lista, item) => {
                    let itemExistente = lista.find(i => i.id === item.id);

                    if (itemExistente) itemExistente.childrens = [...itemExistente.childrens, ...item.childrens];
                    else lista.push(item);

                    return lista;
                }, []);
            }
            else
                $scope.menuList = response.data;
            $scope.totalItems = response.data.length;

        }).catch(function (error) {
            console.error('Error fetching menuList data:', error);
        });
    };

    $scope.getClientsByName = function (name) {
        if (!name || name.length < 3) {
            return [];
        }

        return ClienteService.getTodosSimples(name).then(function (response) {
            return response.data.map(function (item) {
                return item;
            });
        });
    }

    $scope.selectIcon = function (iconName) {
        if ($scope.type == "MENU") {
            $scope.registro.iconRef = `zmdi ${iconName}`;
            $scope.modalListIcons.close();
        } else {
            $scope.function.iconRef = `zmdi ${iconName}`;
            $scope.modalListIcons.close();
        }
    };

    $scope.openListIcons = function (type) {
        $scope.type = type
        $scope.modalListIcons = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/ai_integrations/menus/modal-select-icon.html?t=' + Date.now(),
            scope: $scope,
            controller: function () {

            },
        });
    }

    $scope.selectedFeature = null;
    $scope.selectFeature = function (feature) {
        $scope.selectedFeature = feature;
    };

    $scope.selectedFeatureId = null;

    $scope.selectFeatureId = function (feature) {
        $scope.selectedFeatureId = feature.id;
    };

    $scope.isAssociate = false;

    $scope.onModal = false;

    $scope.openModalMenu = function (menuType, menuData, isAssociate) {
        if ($scope.modalNewMenu) {
            $scope.modalNewMenu.close();
        }

        $scope.onModal = true;

        $scope.function = {};
        $scope.registro = {};

        $scope.isAssociate = !!isAssociate;
        const isMenu = menuType === 'MENU';
        const isFeature = menuType === 'FEATURE';
        const hasDataId = menuData && menuData.id;

        if (isMenu && $scope.isAssociate) {
            $scope.registro = {
                type: "FEATURE"
            };

            $scope.function = {
                parentId: angular.copy(menuData).id,
                clientId: angular.copy(menuData).clientId,
                type: "FEATURE",
                iconType: "ICON",
                clientId: menuData?.clientId,
                aiResponseTarget: {
                    CHAT: false,
                    INPUT: false,
                    TEXT_SELECTION: false
                }
            };
        } else if (isMenu && hasDataId) {
            setTimeout(() => {
                $scope.registro = angular.copy(menuData);
                $scope.function = {
                    iconType: "ICON",
                    type: "FEATURE",
                    aiResponseTarget: {
                        CHAT: false,
                        INPUT: false,
                        TEXT_SELECTION: false
                    }
                };
            }, 50)
        } else {
            $scope.selectedFeature = null;

            $scope.registro = {
                type: menuType || "FEATURE",
                iconType: "ICON"
            };

            $scope.function = {
                iconType: "ICON",
                type: "FEATURE",
                aiResponseTarget: {
                    CHAT: false,
                    INPUT: false,
                    TEXT_SELECTION: false
                }
            };
        }

        if (isFeature) {
            if (hasDataId && !$scope.isAssociate) {
                $scope.function = angular.copy(menuData);

                $timeout(() => {
                    $scope.selectedFeature = $scope.features.find(f => f.id === $scope.function?.promptFeatureId);
                });
            } else {
                $scope.function = {
                    parentId: menuData?.parentId || null,
                    iconType: "ICON",
                    type: "FEATURE",
                    aiResponseTarget: {
                        CHAT: false,
                        INPUT: false,
                        TEXT_SELECTION: false
                    }
                };
            }

            $scope.selectedFeature = null;
        }

        clearUsedFeatures();
        $scope.modalMenu = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/ai_integrations/menus/modal-menu.html?t=' + Date.now(),
            scope: $scope,
            controller: () => {
                
            }
        });
    };

    function clearUsedFeatures() {
        function collectUsedFeatureIds(menuList) {
            const usedIds = new Set();

            function recurse(items) {
                items.forEach(item => {
                    if (item.promptFeatureId !== undefined && item.promptFeatureId !== null) {
                        usedIds.add(item.promptFeatureId);
                    }
                    if (item.childrens && item.childrens.length > 0) {
                        recurse(item.childrens);
                    }
                });
            }

            recurse(menuList);
            return usedIds;
        }

        const usedFeatureIds = collectUsedFeatureIds($scope.menuList);

        const currentFeatureId = $scope.function?.promptFeatureId;
        if (currentFeatureId != null) {
            usedFeatureIds.delete(currentFeatureId);
        }

        $scope.featuresModal = $scope.features.filter(feature => !usedFeatureIds.has(feature.id));
    }

    $scope.newMenu = function () {
        $scope.modalNewMenu = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/ai_integrations/menus/modal-select-type.html?t=' + Date.now(),
            scope: $scope,
            controller: function () {

            },
        });
    }

    $scope.toggleMenu = function (menu) {
        if ((menu.type == "MENU" || menu.type == "SUBMENU") && menu.childrens.length > 0) {
            menu.isOpen = !menu.isOpen;
        }
    };

    $scope.urlImagemCdn = function (base64, fileName) {
        return FileService.insertBase64(base64, fileName).then(function (response) {
            return response.data.url;
        });
    };

    $scope.saveMenu = function () {
        if ($scope.registro.type == 'INITIAL') {
            if (!$scope.initialConfig.client?.id) {
                swal({
                    title: "Atenção!",
                    text: "Selecione o cliente.",
                    type: "info"
                });
            } else {
                MenuAiService.importMenu($scope.initialConfig.client.id).then(() => {
                    $scope.onInit();
                    $scope.modalMenu.close();
                }).catch(error => {
                    swal({
                        title: "Erro!",
                        text: "Erro ao tentar importar menu inicial",
                        details: error?.data?.message || "Erro desconhecido",
                        type: "error",
                        timer: 5000
                    });
                });
            }

            return;
        }

        if ($scope.registro.type == 'MENU') {
            if (!$scope.registro?.name) {
                return swal({
                    title: "Atenção!",
                    text: "O nome do menu é obrigatório.",
                    type: "info"
                });
            }

            if (!$scope.registro?.iconType) {
                return swal({
                    title: "Atenção!",
                    text: "Selecione o tipo de ícone do menu.",
                    type: "info"
                });
            }

            if ($scope.registro.iconType === 'ICON') {
                if (!$scope.registro?.iconRef) {
                    return swal({
                        title: "Atenção!",
                        text: "Insira a classe do ícone do menu.",
                        type: "info"
                    });
                }
            } else if (!$scope.registro.id) {
                if (!$scope.registro?.previewImage) {
                    return swal({
                        title: "Atenção!",
                        text: "Insira a imagem do ícone do menu.",
                        type: "info"
                    });
                }
            }
        } else if ($scope.registro.type == 'FEATURE') {
            if (!$scope.function?.name) {
                return swal({
                    title: "Atenção!",
                    text: "O nome da ação é obrigatório.",
                    type: "info"
                });
            }

            if (!$scope.function.aiResponseTarget.CHAT && !$scope.function.aiResponseTarget.INPUT && !$scope.function.aiResponseTarget.TEXT_SELECTION) {
                return swal({
                    title: "Atenção!",
                    text: "É necessário marcar pelo menos uma origem para a ação",
                    type: "info"
                });
            }

            if ($scope.function.id) {
                if (!$scope.function?.promptFeatureId) {
                    return swal({
                        title: "Atenção!",
                        text: "Selecione uma funcionalidade",
                        type: "info"
                    });
                }
            } else {
                if (!$scope.selectedFeatureId) {
                    return swal({
                        title: "Atenção!",
                        text: "Selecione uma funcionalidade",
                        type: "info"
                    });
                }
            }

            if (!$scope.function?.iconType) {
                return swal({
                    title: "Atenção!",
                    text: "Selecione o tipo de ícone da ação.",
                    type: "info"
                });
            }

            if ($scope.function.iconType === 'ICON') {
                if (!$scope.function?.iconRef) {
                    return swal({
                        title: "Atenção!",
                        text: "Insira a classe do ícone da ação.",
                        type: "info"
                    });
                }
            } else if (!$scope.function.id) {
                if (!$scope.function?.previewImage) {
                    return swal({
                        title: "Atenção!",
                        text: "Insira a imagem do ícone da ação.",
                        type: "info"
                    });
                }
            }
        }

        function getImageUrlIfNeeded(entity, elementId) {
            if (entity !== null && entity.iconType) {
                return new Promise((resolve) => {
                    const input = document.getElementById(elementId);
                    const file = input?.files?.[0];
                    if (entity.iconType === 'IMAGE' && file) {
                        const reader = new FileReader();
                        reader.onload = function (e) {
                            const base64 = e.target.result;
                            $scope.urlImagemCdn(base64, file.name).then(function (url) {
                                entity.iconRef = url;
                                resolve();
                            }).catch(() => resolve());
                        };
                        reader.readAsDataURL(file);
                    } else {
                        resolve();
                    }
                });
            } else {
                return
            }
        }

        const promises = [
            getImageUrlIfNeeded($scope.registro, 'registroImageFile')
        ];

        if (!$scope.registro !== null && !$scope.registro?.id) {
            promises.push(getImageUrlIfNeeded($scope.function, 'functionImageFile'));
        }

        Promise.all(promises).then(function () {
            const isMenu = $scope.registro.type === "MENU";
            const isEdit = $scope.registro.id || $scope.function.id;

            const menuData = {
                id: $scope.registro.id,
                name: $scope.registro.name,
                type: 'MENU',
                iconType: $scope.registro.iconType,
                iconRef: $scope.registro.iconRef,
                clientId: $scope.registro.client?.id ?? ""
            };

            const func = {
                id: $scope.function.id,
                name: $scope.function.name,
                type: 'FEATURE',
                iconType: $scope.function.iconType,
                clientId: $scope.function.client?.id || $scope.function.clientId || menuData.clientId,
                iconRef: $scope.function.iconRef,
                promptFeatureId: $scope.selectedFeatureId || $scope.function.promptFeatureId,
                aiResponseTarget: $scope.function.aiResponseTarget || {
                    CHAT: false,
                    INPUT: false,
                    TEXT_SELECTION: false
                }
            };

            if ($scope.isAssociate) {
                func.parentId = $scope.function.parentId;
            }

            let promise;

            if (isEdit) {
                promise = MenuAiService.updated(isMenu ? menuData : func);
            } else {
                if (isMenu) {
                    promise = MenuAiService.created(menuData);
                } else {
                    promise = MenuAiService.created(func);
                }
            }

            promise.then(() => {
                $scope.onInit();
                $scope.modalMenu.close();
            }).catch(error => {
                swal({
                    title: "Erro!",
                    text: "Erro ao tentar salvar informação",
                    details: error?.data?.message || "Erro desconhecido",
                    type: "error",
                    timer: 5000
                });
            });
        });
    };

    $scope.getMenuListById = function (id) {
        return $scope.menuList.find(function (m) {
            return m.id === id;
        });
    };

    $scope.deleteMenu = function (menu) {
        $scope.onDelete(menu.id);
    };

    $scope.onDelete = (id) => {
        swal({
            title: $translate.instant('ATENCAO') + "!",
            text: "Deseja continuar com a exclusão?",
            type: "warning",
            showCancelButton: true,
            confirmButtonColor: "#DD6B55",
            confirmButtonText: $translate.instant('SIM'),
            cancelButtonText: $translate.instant('CANCELAR'),
            closeOnConfirm: false,
            closeOnCancel: true
        }, function (isConfirm) {
            if (isConfirm) {
                MenuAiService.delete(id).then(function (response) {
                    swal({
                        title: $translate.instant('PRONTO') + "!",
                        text: $translate.instant("ALERT-DELETE-SUCCESS"),
                        type: "success",
                        timer: 5000
                    }, function () {
                        $scope.onInit();
                    });
                }).catch(function (error) {
                    swal({
                        title: "Erro!",
                        text: $translate.instant("ALERT-DELETE-ERRO"),
                        details: error.data.message,
                        type: "error"
                    });
                });
            }
        });
    }

    $scope.triggerFileInput = function (inputId) {
        document.getElementById(inputId).click();
    };

    $scope.handleImageSelect = function (inputElement, type) {
        const file = inputElement.files[0];
        if (file) {
            // console.log(file)
            if (!file.type.startsWith('image/')) {
                swal({
                    title: "Erro!",
                    text: "Por favor, selecione apenas arquivos de imagem.",
                    type: "error"
                });
                inputElement.value = '';
                return;
            }

            const reader = new FileReader();
            reader.onload = function (e) {
                $scope.$apply(function () {
                    if (type === 'registro') {
                        $scope.registro.previewImage = e.target.result;
                    } else if (type === 'function') {
                        $scope.function.previewImage = e.target.result;
                    }
                });
            };
            reader.readAsDataURL(file);
        }
    };

    $scope.$watch('registro.iconType', function (newVal, oldVal) {
        if (oldVal === 'IMAGE' && newVal !== 'IMAGE') {
            $scope.registro.iconRef = null;
            $scope.registro.previewImage = null;

            var fileInput = document.getElementById('registroImageFile');
            if (fileInput) {
                fileInput.value = '';
            }
        }
    });

    $scope.$watch('function.iconType', function (newVal, oldVal) {
        if ($scope.onModal) {
            $scope.onModal = false;
            return
        } else {
            if (oldVal !== 'IMAGE' && newVal === 'IMAGE') {
                $scope.function.iconRef = null;
                $scope.function.previewImage = null;

                var fileInput = document.getElementById('functionImageFile');
                if (fileInput) {
                    fileInput.value = '';
                }
            }
        }
    });

    $scope.importMenu = function () {
        MenuAiService.importMenu($scope.filtro.clientId).then(() => {
            $scope.onInit();
        }).catch(error => {
            swal({
                title: "Erro!",
                text: "Erro ao tentar importar menu inicial",
                details: error?.data?.message || "Erro desconhecido",
                type: "error",
                timer: 5000
            });
        });
    };
});
;

materialAdmin.service('MenuAiService', function ($http, $setting) {
    this.getAll = function (filtro) {
        return $http({
            method: "get",
            url: $setting.api + "/ai-integrations/prompt-feature-menu",
            params: filtro,
            isArray: true
        });
    };

    this.delete = (id) => {
        return $http({
            method: "delete",
            url: $setting.api + "/ai-integrations/prompt-feature-menu/" + id
        });
    };

    this.updated = (menu) => {
        return $http({
            method: "put",
            url: $setting.api + "/ai-integrations/prompt-feature-menu",
            data: menu
        });
    };

    this.created = (menu) => {
        return $http({
            method: "post",
            url: $setting.api + "/ai-integrations/prompt-feature-menu",
            data: menu
        });
    };

    this.importMenu = (clientId) => {
        return $http({
            method: "post",
            url: $setting.api + "/ai-integrations/prompt-feature-menu/import",
            params: { clientId }
        });
    }
});

    
