materialAdmin.service('BotFacebookService', function ($http, $setting) {

    this.iniciarBot = function (botFacebook, isClient) {
        var botFacebookCopy = Object.assign({}, botFacebook);
        
        var requestConf = {
            method: "post",
            url: $setting.api + "/bots_facebook/iniciar",
            data: botFacebookCopy
        };
        
        return $http(requestConf)
            .then(function (response) {
                if (response.status == 206) {
                    swal("Ops!", response.data.message, "error");
                    return Promise.reject(response.status);
                }
                            
                if (response.status == 205)
                    return Promise.reject(response.status);
                    /*return new Promise(function (resolve, reject) {
                        FB.login(function (fb_response) {
                            if (fb_response.status == "connected")
                                botFacebookCopy.userAccessToken = fb_response.authResponse.accessToken;
                            
                            resolve();
                        }, { scope: 'public_profile,email,manage_pages,pages_messaging' });
                        
                        setTimeout(reject, 300000);
                    });*/
            })
            .then(function () { return $http(requestConf) })
            .catch(function (responseStatus) {
                if (responseStatus === 205 && isClient)
                    return Promise.reject();
            });
    };
    
    this.pararBot = function (botFacebook) {
        var request = $http({
            method: "post",
            url: $setting.api + "/bots_facebook/" + botFacebook.id + "/parar",
            data: botFacebook
        });

        return (request);
    };
    
    this.fazerLogoffBot = function (botFacebook) {
        var request = $http({
            method: "post",
            url: $setting.api + "/bots_facebook/" + botFacebook.id + "/logoff",
            data: botFacebook
        });

        return (request);
    };

    this.forceSubscribe = function (botFacebook) {
        var request = $http({
            method: "post",
            url: $setting.api + "/bots_facebook/" + botFacebook.id + "/force-subscribe",
            data: botFacebook
        });

        return (request);
    };

    this.atualizarApelido = function (id, apelido) {
        return $http({
            method: "put",
            url: $setting.api + "/bots_facebook/" + id + "/apelido",
            data: { apelido: apelido }
        });
    };

});

