        // ==========================================================
// EMOJIS
// ==========================================================

$scope.emojiListControl = {
    opened: false,
    activeTab: 0,
    emojis: [],
    recentEmojis: []
};

$scope.emojiList = [];

// ----------------------------------------------------------
// ABA ANTERIOR
// ----------------------------------------------------------

$scope.selectPreviousEmojiTab = function () {
    $scope.selectEmojiTab(
        $scope.emojiListControl.activeTab - 1
    );
};

// ----------------------------------------------------------
// PRÓXIMA ABA
// ----------------------------------------------------------

$scope.selectNextEmojiTab = function () {
    $scope.selectEmojiTab(
        $scope.emojiListControl.activeTab + 1
    );
};

// ----------------------------------------------------------
// SELECIONAR ABA
// ----------------------------------------------------------

$scope.selectEmojiTab = function (index) {

    if (!$scope.emojiList || !$scope.emojiList.length) {
        $scope.emojiListControl.activeTab = 0;
        $scope.emojiListControl.emojis = [];
        return;
    }

    if (index < 0) {
        index = 0;
    }

    if (index >= $scope.emojiList.length) {
        index = $scope.emojiList.length - 1;
    }

    $scope.emojiListControl.activeTab = index;

    $scope.emojiListControl.emojis =
        $scope.emojiList[index].emojis || [];
};

// ----------------------------------------------------------
// ABRIR / FECHAR LISTA
// ----------------------------------------------------------

$scope.toggleEmojiList = function () {
    $scope.emojiListControl.opened =
        !$scope.emojiListControl.opened;
};

// ----------------------------------------------------------
// CARREGAR EMOJIS
// ----------------------------------------------------------

$scope.getEmojiList = function () {

    // Garantir estrutura dos recentes
    if (!$localStorage.recentEmojis) {
        $localStorage.recentEmojis = [];
    }

    $scope.emojiListControl.recentEmojis =
        $localStorage.recentEmojis;

    // NÃO usar $resource aqui.
    // O arquivo é apenas um JSON estático.
    $http({
        method: "GET",
        url: "data/emoji.json",
        cache: true
    }).then(function (response) {

        var data = response.data;

        var emojis = [];

        // Aceita:
        // {
        //   "emojis": [...]
        // }
        if (data && angular.isArray(data.emojis)) {
            emojis = data.emojis;
        }

        // Também aceita JSON diretamente como array
        else if (angular.isArray(data)) {
            emojis = data;
        }

        $scope.emojiList = [];

        // Nenhum emoji
        if (!emojis.length) {
            $scope.emojiListControl.activeTab = 0;
            $scope.emojiListControl.emojis = [];
            return;
        }

        // Agrupar por categoria
        var grupos = {};

        angular.forEach(emojis, function (item) {

            if (!item) {
                return;
            }

            var categoria =
                item.category ||
                item.categoria ||
                "Outros";

            if (!grupos[categoria]) {
                grupos[categoria] = [];
            }

            grupos[categoria].push(item);
        });

        // Criar lista das categorias
        angular.forEach(grupos, function (lista, categoria) {

            if (!lista || !lista.length) {
                return;
            }

            $scope.emojiList.push({
                name: categoria,
                icon: lista[0].emoji || "",
                emojis: lista
            });
        });

        // Selecionar primeira categoria
        if ($scope.emojiList.length > 0) {
            $scope.selectEmojiTab(0);
        } else {
            $scope.emojiListControl.activeTab = 0;
            $scope.emojiListControl.emojis = [];
        }

    }, function (error) {

        console.error(
            "Erro ao carregar data/emoji.json:",
            error
        );

        $scope.emojiList = [];

        $scope.emojiListControl.activeTab = 0;
        $scope.emojiListControl.emojis = [];
    });
};

        $scope.onModalEmojis =
            function () {

                $scope.modalEmojis =
                    $uibModal.open({

                        templateUrl:
                            "views/smbot/perguntas/modal-emojis.html?t=" +
                            Date.now(),

                        scope: $scope,

                        size: "lg"
                    });
            };


        $scope.onSelecionarEmoji =
            function (emoji) {

                if (!emoji) {
                    return;
                }

                $scope.emojiSelecionado =
                    emoji;

                if (
                    !$localStorage.recentEmojis
                ) {

                    $localStorage.recentEmojis =
                        [];
                }

                var recentes =
                    $localStorage
                        .recentEmojis;

                var index =
                    recentes.indexOf(
                        emoji
                    );

                if (index >= 0) {
                    recentes.splice(
                        index,
                        1
                    );
                }

                recentes.unshift(
                    emoji
                );

                if (
                    recentes.length > 20
                ) {

                    recentes.length =
                        20;
                }

                $scope.emojiListControl
                    .recentEmojis =
                    recentes;

                if (
                    $scope.modalEmojis
                ) {

                    $scope.modalEmojis
                        .close(emoji);
                }
            };


