materialAdmin.service("FileService", [
    "$http",
    "$setting",
    function ($http, $setting) {

        var baseUrl = "https://banco-arquivo.n3bot.com.br/api/upload";


        // ==========================================================
        // UPLOAD DE ARQUIVO
        // ==========================================================

        this.upload = function (arquivo, dados) {

            var formData = new FormData();

            formData.append("file", arquivo);

            if (dados) {

                Object.keys(dados).forEach(function (key) {

                    if (
                        dados[key] !== undefined &&
                        dados[key] !== null
                    ) {

                        formData.append(
                            key,
                            dados[key]
                        );

                    }

                });

            }

            return $http.post(
                baseUrl,
                formData,
                {
                    transformRequest: angular.identity,

                    headers: {
                        "Content-Type": undefined
                    }
                }
            );

        };


        // ==========================================================
        // REMOVER ARQUIVO
        // ==========================================================

        this.remover = function (arquivo) {

            return $http.delete(
                baseUrl,
                {
                    params: {
                        arquivo: arquivo
                    }
                }
            );

        };


        // ==========================================================
        // LISTAR ARQUIVOS
        // ==========================================================

        this.listar = function (filtros) {

            return $http.get(
                baseUrl,
                {
                    params: filtros || {}
                }
            );

        };


        // ==========================================================
        // CRIAR PASTA
        // ==========================================================

        this.criarPasta = function (dados) {

            return $http.post(
                baseUrl + "/pasta",
                dados || {}
            );

        };


        // ==========================================================
        // MOVER ARQUIVO
        // ==========================================================

        this.mover = function (
            arquivo,
            pasta
        ) {

            return $http.put(
                baseUrl + "/mover",
                {
                    arquivo: arquivo,
                    pasta: pasta
                }
            );

        };


        // ==========================================================
        // EDITAR COMPARTILHAMENTO
        // ==========================================================

        this.editarCompartilhamento = function (
            arquivo,
            dados
        ) {

            return $http.put(
                baseUrl + "/compartilhamento",
                {
                    arquivo: arquivo,
                    dados: dados
                }
            );

        };


        // ==========================================================
        // OBTER ARQUIVO
        // ==========================================================

        this.obter = function (arquivo) {

            return $http.get(
                baseUrl + "/arquivo",
                {
                    params: {
                        arquivo: arquivo
                    }
                }
            );

        };

    }
]);


