    $scope.onReiniciarBot = function (telefone, refresh, callback) {

        $scope.jwt = jwt_decode($localStorage.token);

        //parando

        ClienteService.pararServico(telefone.telefoneId).then(
            function success() {

                //iniciando

                setTimeout(function () {
                    ClienteService.iniciarServico(telefone.telefoneId).then(function () {

                        if (refresh) {

                            swal({
                                title: $translate.instant('PRONTO') + "!",
                                text: "Esse bot foi reiniciado. Aguarde alguns segundos para o serviço iniciar por completo.",
                                type: "success",
                                timer: 7000,
                                function() {
                                    callback();
                                }
                            });
                        } else {
                            if (callback) {
                                callback();
                            }
                        }
                    });
                }, 1000);

            },
            function error() {

                setTimeout(function () {

                    //iniciando

                    ClienteService.iniciarServico(telefone.telefoneId).then(function () {

                        if (refresh) {

                            swal({
                                title: $translate.instant('PRONTO') + "!",
                                text: "Esse bot foi reiniciado. Aguarde alguns segundos para o serviço iniciar por completo.",
                                type: "success",
                                timer: 7000,
                                function() {
                                    callback();
                                }
                            });
                        } else {
                            if (callback) {
                                callback();
                            }
                        }

                    });

                }, 1000);

            }
        );
    };

