    $scope.onEditarPerfil = function (telefone) {
        $scope.modalEditarPerfil = $uibModal.open({
            animation: true,
            backdrop: 'static',
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/smbot/perguntas//modal-editar-perfil.html?t=' + NO_CACHE,
            scope: $scope,
            size: 'lg',
            controller: function () {
                $scope.profile = {};
                $scope.profile.telefone = telefone.telefoneId;

                TSZDialogService.get($scope.profile.telefone)
                    .then(res => {
                        $scope.profile = res.data;

                        if ($scope.profile.websites) {
                            $scope.profile.websites = $scope.profile.websites.toString();
                        }

                        if ($scope.profile.photo) {
                            $scope.selectImagePerfil($scope.profile.photo);
                        }

                        updateComponentsAfterRequest();
                    })

                $scope.saveProfile = function () {
                    let profile = angular.copy($scope.profile)

                    if (profile.websites) {
                        profile.websites = profile.websites.split(',');
                    }

                    TSZDialogService.update(profile).then(function (response) {
                        swal("Pronto!", "Registro atualizado com sucesso.", "success", 2000);
                        $scope.modalEditarPerfil.close();
                    });
                };
            }
        });

        $scope.modalEditarPerfil.rendered.then(function () {
            angular.element("#image-input")
                .on('change.bs.fileinput',
                    function (event, data) {
                        $scope.updateImagePerfil(data);
                    });

            angular.element("#image-input")
                .on('clear.bs.fileinput',
                    function (event) {
                        $scope.updateImagePerfil(null);
                    });
        });
    };

    $scope.updateImagePerfil = function (image) {
        if (image !== null) {
            FileService.insertBase64(image.result, "photo.png").then(function (response) {
                $scope.profile.photo = response.data.url;
                $scope.selectImagePerfil($scope.profile.photo);
            });
        } else {
            $scope.profile.photo = undefined;
            $scope.selectImagePerfil();
        }
    };

    $scope.selectImagePerfil = function (url) {
        if (url) {
            $(`#image-input img`).attr('src', url);
            $(`#image-input span.fileinput-new`).hide();
            $(`#image-input span.fileinput-exists`).show();
            $(`#image-input a.fileinput-exists`).show().css({ 'display': 'block' });
        } else {
            $(`#image-input img`).removeAttr('src');
            $(`#image-input span.fileinput-new`).show();
            $(`#image-input span.fileinput-exists`).hide();
            $(`#image-input a.fileinput-exists`).hide();
        }
    };

