    $scope.onModalSalvarBotEmail = function () {
        if (!$scope.edicaoBotEmail.imapUser || $scope.edicaoBotEmail.imapUser == "") {
            return swal("Ops!", "O usuário de recebimento é obrigatório", "error");
        }

        if (!$scope.edicaoBotEmail.imapHost || $scope.edicaoBotEmail.imapHost == "") {
            return swal("Ops!", "O host de recebimento é obrigatório", "error");
        }

        if (!$scope.edicaoBotEmail.imapHost.match(/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9][a-z0-9-]{0,61}[a-z0-9]$/)) {
            return swal("Ops!", "Insira um domínio de recebimento válido", "error");
        }

        if (!$scope.edicaoBotEmail.imapPort || $scope.edicaoBotEmail.imapPort == "") {
            return swal("Ops!", "A porta de recebimento é obrigatória", "error");
        }

        if (!$scope.edicaoBotEmail.smtpUser || $scope.edicaoBotEmail.smtpUser == "") {
            return swal("Ops!", "O usuário de envio é obrigatório", "error");
        }

        if (!$scope.edicaoBotEmail.smtpHost || $scope.edicaoBotEmail.smtpHost == "") {
            return swal("Ops!", "O host de envio é obrigatório", "error");
        }

        if (!$scope.edicaoBotEmail.smtpHost.match(/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9][a-z0-9-]{0,61}[a-z0-9]$/)) {
            return swal("Ops!", "Insira um domínio de envio válido", "error");
        }

        if (!$scope.edicaoBotEmail.smtpPort || $scope.edicaoBotEmail.smtpPort == "") {
            return swal("Ops!", "A porta de envio é obrigatória", "error");
        }

        if ($scope.edicaoBotEmail.id === undefined) {
            if (!$scope.edicaoBotEmail.imapPassword || $scope.edicaoBotEmail.imapPassword == "") {
                return swal("Ops!", "A senha de recebimento é obrigatória", "error");
            }

            if (!$scope.edicaoBotEmail.smtpPassword || $scope.edicaoBotEmail.smtpPassword == "") {
                return swal("Ops!", "A senha de envio é obrigatória", "error");
            }
        }

        BotEmailGrupoPerguntaService.atualizar($scope.edicaoBotEmail).then(function () {
            swal({
                title: $translate.instant('PRONTO') + "!",
                text: $translate.instant('REGISTRO-ATUALIZADO'),
                type: "success",
                timer: 2000,
            }, function () {
                $scope.modalBotEmail.close();
                $scope.edicaoBotEmail = null;
            });
        });
    };

