materialAdmin.constant("recaptchaConfig", {
    siteKey: "6LfGYMosAAAAAEcIfzcjJUVgVTrm4F-KyFkVJK5U"
});

materialAdmin.directive("clickOutsideLogin", function($document) {

    return {
        restrict: "A",
        link: function(scope, element, attributes) {

            function fechar(event) {

                if (element[0].contains(event.target)) {
                    return;

                }

                scope.$applyAsync(function() {
                    scope.$eval(attributes.clickOutsideLogin);
                });

            }

            $document.on("click", fechar);

            scope.$on("$destroy", function() {
                $document.off("click", fechar);
            });

        }
    };

});

materialAdmin.directive("recaptchaWidget", function($timeout, recaptchaConfig) {

    return {
        restrict: "A",
        scope: {
            token: "="
        },
        link: function(scope, element) {

            var widgetId;

            function render() {

                if (widgetId !== undefined ||
                    typeof grecaptcha === "undefined") {

                    return;

                }

                widgetId = grecaptcha.render(element[0], {
                    sitekey: recaptchaConfig.siteKey,
                    callback: function(token) {
                        scope.$applyAsync(function() {
                            scope.token = token;
                        });
                    },
                    "expired-callback": function() {
                        scope.$applyAsync(function() {
                            scope.token = "";
                        });
                    },
                    "error-callback": function() {
                        scope.$applyAsync(function() {
                            scope.token = "";
                        });
                    }
                });

            }

            function onReady() {
                $timeout(render);
            }

            window.addEventListener("recaptchaready", onReady);
            onReady();

            scope.$on("$destroy", function() {
                window.removeEventListener("recaptchaready", onReady);
            });

        }
    };

});


