materialAdmin.factory('ServidorService', function ($http, $setting) {

    var api = $setting.api;

    return {

        // Lista todos os servidores
        getTodos: function () {
            return $http.get(
                api + '/servidores'
            );
        },

        // Busca um servidor pelo ID
        get: function (id) {
            return $http.get(
                api + '/servidores/' + id
            );
        },

        // Insere um novo servidor
        inserir: function (registro) {
            return $http.post(
                api + '/servidores',
                registro
            );
        },

        // Cria um novo servidor
        criar: function () {
            return $http.post(
                api + '/servidores/criar'
            );
        },

        // Atualiza servidor
        atualizar: function (registro) {
            return $http.put(
                api + '/servidores/' + registro.id,
                registro
            );
        },

        // Remove servidor
        remover: function (id) {
            return $http.delete(
                api + '/servidores/' + id
            );
        },

        // Atualiza somente o status
        atualizarStatus: function (registro) {
            return $http.put(
                api + '/servidores/' + registro.id + '/status',
                {
                    ativo: registro.ativo
                }
            );
        },

        // Invalida servidor
        invalidar: function (id) {
            return $http.put(
                api + '/servidores/' + id + '/invalidar'
            );
        },

        // Para os bots de um servidor
        stopBots: function (id) {
            return $http.post(
                api + '/servidores/' + id + '/stop-bots'
            );
        },

        // Para todos os bots
        stopAllBots: function () {
            return $http.post(
                api + '/servidores/stop-all-bots'
            );
        },

        // Realoca os bots
        realocar: function () {
            return $http.post(
                api + '/servidores/realocar'
            );
        }

    };

});




materialAdmin.controller('ServidorEdicaoController', function (
    $scope,
    $translate,
    $location,
    $routeParams,
    ServidorService
) {

    $scope.registro = {};

    $scope.onInit = function () {

        var id = $routeParams.id;

        ServidorService.get(id).then(function (response) {

            $scope.registro = response.data;

            updateComponentsAfterRequest();

        });

    };

    $scope.onSalvar = function () {

        ServidorService.atualizar(
            $scope.registro
        ).then(function () {

            swal({
                title: $translate.instant('PRONTO') + "!",
                text: $translate.instant('REGISTRO-ATUALIZADO'),
                type: "success",
                timer: 2000
            });

            $location.path('#/cadastros/servidores');

        });

    };

    $scope.onRemover = function (registro) {

        servidorUtils.remover(
            $translate,
            ServidorService,
            registro,
            function () {

                $location.path(
                    '#/cadastros/servidores'
                );

            }
        );

    };

});


var servidorUtils = {

    remover: function (
        $translate,
        ServidorService,
        registro,
        callback
    ) {

        swal({
            title: $translate.instant('ATENCAO') + "!",
            text: $translate.instant("REMOVER-REGISTRO"),
            type: "warning",

            showCancelButton: true,

            confirmButtonColor: "#DD6B55",
            confirmButtonText: $translate.instant('SIM'),
            cancelButtonText: $translate.instant('CANCELAR'),

            closeOnConfirm: false,
            closeOnCancel: true

        }, function (isConfirm) {

            if (!isConfirm) {
                return;
            }

            ServidorService.remover(
                registro.id
            ).then(function () {

                swal({
                    title: $translate.instant('PRONTO') + "!",
                    text: $translate.instant("REGISTRO-REMOVIDO"),
                    type: "success",
                    timer: 2000
                });

                if (typeof callback === 'function') {
                    callback();
                }

            });

        });

    },


    alterarStatus: function (
        $translate,
        ServidorService,
        registro,
        callback
    ) {

        var statusPergunta = registro.ativo
            ? $translate.instant('ATIVAR')
            : $translate.instant('INATIVAR');

        swal({
            title: $translate.instant('ATENCAO') + "!",
            text: $translate.instant(
                'STATUS-REGISTRO',
                {
                    status: statusPergunta
                }
            ),

            type: "warning",

            showCancelButton: true,

            confirmButtonColor: "#DD6B55",
            confirmButtonText: $translate.instant('SIM'),
            cancelButtonText: $translate.instant('CANCELAR'),

            closeOnConfirm: false,
            closeOnCancel: true

        }, function (isConfirm) {

            if (!isConfirm) {
                return;
            }

            ServidorService.atualizarStatus(
                registro
            ).then(function () {

                swal({
                    title: $translate.instant('PRONTO') + "!",
                    text: $translate.instant('REGISTRO-ATUALIZADO'),
                    type: "success",
                    timer: 2000
                });

                if (typeof callback === 'function') {
                    callback();
                }

            });

        });

    }

};


