                        name: 'AI-ASSISTANT',
                        sref: 'ai_integrations.assitant',
                        condition: () => $scope.isAdministrador() || $scope.isRevendedor() || (($scope.isGestor() || $scope.isSupervisorChatbot({ module: 'MODULE_AI', page: 'PAGE_AI_ASSISTANTS' })) && $scope.permissions && $scope.permissions.permissionIAs && $scope.permissions.permissionCriarEditarAis)
