materialAdmin.controller("BotsController", function ($scope, $http) {
    var paginaBots = document.querySelector(".mz-page-content");
    if (paginaBots) {
        paginaBots.classList.add("n3bots-host");
    }

    $scope.$on("$destroy", function () {
        if (paginaBots) {
            paginaBots.classList.remove("n3bots-host");
        }
        document.removeEventListener("click", cliqueContinuar);
    });

    /*
     * Copie o Configuration ID em:
     * Meta for Developers > Seu App > Facebook Login for Business > Configurations.
     */
    var META_EMBEDDED_SIGNUP_CONFIG_ID = "1108304251662058";
    // Deve ser igual a META_REDIRECT_URI do .env e estar cadastrado na Meta.
    var META_REDIRECT_URI = window.location.origin + window.location.pathname;
    $scope.bots = [
        { nome: "Atendimento Comercial", descricao: "Bot de vendas e qualificação", canal: "WhatsApp", status: "ativo", atualizado: "Atualizado hoje, 10:42" },
        { nome: "Suporte N3", descricao: "Triagem e suporte ao cliente", canal: "API Oficial", status: "ativo", atualizado: "Atualizado ontem, 16:20" },
        { nome: "Pesquisa Pós-venda", descricao: "Coleta de satisfação", canal: "WhatsApp", status: "rascunho", atualizado: "Criado em 14 set." }
    ];
    $scope.filtroStatus = "";
    $scope.quantidadeAtivos = function () {
        return $scope.bots.filter(function (bot) { return bot.status === "ativo"; }).length;
    };
    $scope.filtrarStatus = function (bot) {
        return !$scope.filtroStatus || bot.status === $scope.filtroStatus;
    };
    $scope.abrirCriacao = function () {
        $scope.modalAberto = true;
        $scope.etapa = 1;
        $scope.novoBot = { canal: "WhatsApp", nome: "", descricao: "" };
    };
    $scope.avancarCriacao = function ($event) {
        if ($event) {
            $event.preventDefault();
            $event.stopPropagation();
        }
        $scope.etapa = 2;
    };
    /*
     * Fallback para o tema legado: ele pode envolver o ng-view em um form e
     * transformar botões sem type em submit. Mantém o fluxo em Angular.
     */
    function cliqueContinuar(event) {
        var alvo = event.target.closest
            ? event.target.closest(".n3bots-card .n3bots-primary")
            : null;

        if (!alvo || alvo.textContent.trim() !== "Continuar") {
            return;
        }

        event.preventDefault();
        $scope.$applyAsync(function () {
            $scope.etapa = 2;
        });
    }

    document.addEventListener("click", cliqueContinuar);
    $scope.fecharCriacao = function () {
        $scope.modalAberto = false;
        $scope.qrAberto = false;
        $scope.qrImagem = null;
        $scope.qrErro = null;
    };
    $scope.abrirQrCode = function () {
        $scope.qrAberto = true;
        $scope.gerarQrCode();
    };
    $scope.fecharQrCode = function () {
        $scope.qrAberto = false;
        $scope.qrImagem = null;
        $scope.qrErro = null;
    };
    $scope.gerarQrCode = function () {
        $scope.qrCarregando = true;
        $scope.qrErro = null;
        $scope.qrImagem = null;

        $http.get("https://socket.n3bot.com.br/qr", {
            headers: {
                "ngrok-skip-browser-warning": "true",
                "Content-Type": "application/json"
            }
        }).then(function (response) {
            var dados = response.data || {};
            var qr = dados.qr || dados.qrCode || "";

            if (!qr) {
                $scope.qrErro = "Nenhum QR Code disponível. Tente atualizar.";
                return;
            }

            // O serviço pode responder data URL, URL pública ou base64 puro.
            $scope.qrImagem = /^(data:|https?:)/i.test(qr)
                ? qr
                : "data:image/png;base64," + qr;
        }).catch(function () {
            $scope.qrErro = "Não foi possível acessar o servidor do WhatsmaterialAdmin.";
        }).finally(function () {
            $scope.qrCarregando = false;
        });
    };
    $scope.conectarMeta = function () {
        $scope.erroMeta = null;

        if (META_EMBEDDED_SIGNUP_CONFIG_ID === "1108304251662058") {
            $scope.erroMeta = "Configure o META_EMBEDDED_SIGNUP_CONFIG_ID no BotsController.";
            return;
        }

        if (
            !window.N3BOT_META_APP_ID ||
            window.N3BOT_META_APP_ID === "2441172036401505"
        ) {
            $scope.erroMeta = "Configure o App ID da Meta no index.html.";
            return;
        }

        if (!window.FB || !window.FB.login) {
            $scope.erroMeta = "O SDK da Meta ainda está carregando. Aguarde alguns segundos e tente novamente.";
            return;
        }

        $scope.conectandoMeta = true;
        window.FB.login(function (response) {
            if (!response || !response.authResponse || !response.authResponse.code) {
                $scope.$applyAsync(function () {
                    $scope.conectandoMeta = false;
                    $scope.erroMeta = "A conexão com a Meta foi cancelada ou não autorizada.";
                });
                return;
            }

            /*
             * O backend deve trocar este code por um token e guardar os dados
             * da conta (WABA ID e Phone Number ID). Nunca faça isso no navegador.
             */
            $http.post("api/meta-whatsapp-callback.php", {
                code: response.authResponse.code
            }).then(function (resposta) {
                var dados = resposta.data || {};
                $scope.novoBot.metaConectada = true;
                $scope.novoBot.wabaId = dados.waba_id || dados.wabaId;
                $scope.novoBot.phoneNumberId = dados.phone_number_id || dados.phoneNumberId;
            }).catch(function () {
                $scope.erroMeta = "Não foi possível concluir a vinculação no servidor.";
            }).finally(function () {
                $scope.conectandoMeta = false;
            });
        }, {
            config_id: 1108304251662058,
            redirect_uri: META_REDIRECT_URI,
            response_type: "code",
            override_default_response_type: true,
            extras: {
                setup: {},
                featureType: "whatsapp_business_app_onboarding"
            }
        });
    };
    $scope.criarBot = function () {
        if (!$scope.novoBot.nome || !$scope.novoBot.nome.trim()) {
            window.alert("Informe um nome para o bot.");
            return;
        }
        $scope.bots.unshift({
            nome: $scope.novoBot.nome.trim(),
            descricao: $scope.novoBot.descricao || "Novo bot em configuração",
            canal: $scope.novoBot.canal,
            status: "rascunho",
            atualizado: "Criado agora"
        });
        $scope.fecharCriacao();
    };
    $scope.mostrarAviso = function (mensagem) { window.alert(mensagem); };
});

var SocketUtil = {

    instance: null,
    rooms: [],
    log: [],

    addLog: (text) => {
        //console.log(text);
        SocketUtil.log.push(new Date() + " | " + text);
    },

    initialize: (token) => {
        try {
            if (!SocketUtil.instance) {

                if (!token) {
                    return;
                }

                var jwt = jwt_decode(token);
                var endpoint = (jwt.usuarioId % 2 == 0 || jwt.usuarioPerfil === Perfil.GESTOR || jwt.usuarioPerfil === Perfil.SUPERVISOR_CHATBOT) ? 'https://notification-n001.n3bot.com.br' : 'https://notification-n002.n3bot.com.br';

                SocketUtil.instance = io(endpoint, {
                    auth: {
                        token: token
                    },
                    transports: ['websocket']
                });

                SocketUtil.instance.on('connect', () => {
                    SocketUtil.addLog("SOCKET CONNECT");

                    if (SocketUtil.rooms.length) {
                        for (room of SocketUtil.rooms) {
                            SocketUtil.instance.emit('join', room);

                            if (room.includes('helpdesk')) {
                                SocketUtil.addLog('LISTENING EVENT (RECONNECT): ' + room);
                            }

                        }
                    }
                });

                SocketUtil.instance.on("connect_error", (data) => {
                    SocketUtil.addLog("SOCKET ERROR: " + data);
                });

                SocketUtil.instance.on("disconnect", (data) => {
                    SocketUtil.addLog("SOCKET DISCONNECT: " + data);
                });
            }
        } catch (e) {
            console.error(e);
        }
    },

    disconnect: () => {
        try {
            if (SocketUtil.instance) {
                SocketUtil.instance.disconnect();

                delete SocketUtil.instance;
                delete SocketUtil.rooms;
            }
        } catch (e) {
            console.error(e);
        }
    },

    emmit: (to, event, value) => {
        try {
            let payload = {
                to: to,
                name: event,
                value: value
            }

            SocketUtil.instance.emit('event', payload);
        } catch (e) {
            console.error(e);
        }
    },

    startListener: (eventName, callback) => {
        try {
            SocketUtil.rooms.push(eventName);

            if (SocketUtil.instance.connected) {
                SocketUtil.instance.emit('join', eventName);

                if (eventName.includes('helpdesk')) {
                    SocketUtil.addLog('LISTENING EVENT: ' + eventName);
                }

            }

            SocketUtil.instance.on(eventName, (data) => {
                if (callback) {
                    callback(data);
                }
            });

            let ref = {
                eventName: eventName,
                off: () => {
                    try {
                        SocketUtil.rooms.splice(SocketUtil.rooms.indexOf(eventName), 1);

                        SocketUtil.instance.emit('leave', eventName);
                        SocketUtil.instance.off(eventName);

                        if (eventName.includes('helpdesk')) {
                            SocketUtil.addLog('OFF EVENT:' + eventName);
                        }
                    } catch (e) {
                        console.log(e);
                    }
                }
            }

            return ref;
        } catch (e) {
            console.log(e);
        }
    },
};;

