        $scope.hasTutorial = function (chave) {
            if ($scope.isGestor() || $scope.isAtendente() || $scope.isSupervisorRevenda() || $scope.isSupervisorChatbot() || $scope.isSupervisorDelivery()) {
                return false;
            }

            if (!$scope.tutoriais || $scope.tutorialVisible == '0') {
                return false;
            }

            var tutorial = $scope.tutoriais.filter(function (a) {
                return a.chave === chave;
            });

            return tutorial.length > 0 && tutorial[0].link;
        };

