        $scope.showTutorial = function (chave, event) {
            if (event) {
                event.preventDefault();
                event.stopPropagation();
            }

            $scope.tutorial = undefined;

            var tutorial = $scope.tutoriais.filter(function (a) {
                return a.chave === chave;
            });

            if (tutorial.length > 0 && tutorial[0].link) {
                $scope.tutorial = tutorial[0];

                if ($scope.tutorial.link.indexOf("pdf") > -1) {
                    $scope.tutorialSrc = tutorial[0].link;
                    $window.open($scope.tutorialSrc, "_blank", "location=no,enableviewportscale=yes");
                } else {
                    $scope.tutorialSrc = $sce.trustAsResourceUrl($scope.tutorial.link);

                    $scope.tutorialModal = $uibModal.open({
                        animation: true,
                        ariaLabelledBy: 'modal-title-top',
                        ariaDescribedBy: 'modal-body-top',
                        templateUrl: 'template/modal-tutorial-video.html',
                        size: 'lg',
                        scope: $scope
                    });
                }
            }
        };

