        $scope.onTaskDone = function () {
            if ($scope.editMode) {
                TaskService.cancel($scope.id, $scope.task.description).then(function (response) {
                    swal({
                        title: "Sucesso!",
                        text: "Task cancelada com sucesso",
                        details: response.data.message,
                        type: "success",
                        timer: 2000
                    }, function () {
                        if ($scope.modalTaskDone) $scope.modalTaskDone.close();
                        if ($scope.modalEvento) $scope.modalEvento.close();
                        UsuarioService.getNotifications().then(function (res) {
                            $scope.userNotifications = res.data;
                        });
                    });
                }).catch(function (error) {
                    swal({
                        title: "Erro!",
                        text: "Erro ao tentar cancelar a task",
                        details: error.data && error.data.message,
                        type: "error",
                        timer: 5000
                    });
                });
            } else {
                TaskService.done($scope.id, $scope.task.description).then(function (response) {
                    swal({
                        title: "Sucesso!",
                        text: "Task concluida com sucesso",
                        details: response.data.message,
                        type: "success",
                        timer: 2000
                    }, function () {
                        if ($scope.modalTaskDone) $scope.modalTaskDone.close();
                        if ($scope.modalEvento) $scope.modalEvento.close();
                        UsuarioService.getNotifications().then(function (res) {
                            $scope.userNotifications = res.data;
                        });
                    });
                }).catch(function (error) {
                    swal({
                        title: "Erro!",
                        text: "Erro ao tentar concluir a task",
                        details: error.data && error.data.message,
                        type: "error",
                        timer: 5000
                    });
                });
            }
        };

