        $scope.addNotification = function (data) {
            $scope.permissions = $scope.permissions || {};
            $scope.userNotifications = $scope.userNotifications || [];

            $scope.permissions.totalNotifications = ($scope.permissions.totalNotifications || 0) + 1;
            $scope.$apply();

            var newNotification = data.notification;

            var existingNotificationIndex = $scope.userNotifications.findIndex(function (notification) {
                return notification.id === newNotification.id;
            });

            if (existingNotificationIndex > -1) {
                $scope.userNotifications[existingNotificationIndex] = newNotification;
            } else {
                $scope.userNotifications.push(newNotification);
            }

            if (newNotification.crmTaskId) {
                $scope.openInTask(newNotification.crmTaskId);
            }

            if (newNotification.type == "SOLICITACAO_PARTICIPACAO") {
                $scope.openInSolicitation(newNotification);
            }

            // $scope.dadosNotificacao = newNotification;

            // $scope.modalNotificationInfo = $uibModal.open({
            //     animation: true,
            //     ariaLabelledBy: 'modal-title-top',
            //     ariaDescribedBy: 'modal-body-top',
            //     templateUrl: 'views/crm/modal-info-notification.html',
            //     scope: $scope,
            //     size: 'lg'
            // })
        };

        $scope.removeNotification = function (data) {
            if ($scope.permissions.totalNotifications > 0) {
                $scope.permissions.totalNotifications--;
            }

            if ($scope.userNotifications.length) {
                const notificationIndex = $scope.userNotifications.findIndex(function (notification) {
                    return notification.id == data.notification.id;
                });

                if (notificationIndex > -1) {
                    $scope.userNotifications.splice(notificationIndex, 1);
                }
            }
        };

        $scope.removeAllNotification = function () {
            if ($scope.permissions.totalNotifications > 0) {
                $scope.permissions.totalNotifications = 0;
            }

            $scope.userNotifications = [];
        };


