        $scope.updateOpenMerchant = function (open) {
            var merchant = angular.copy($scope.selectedMerchant);
            merchant.open = open;

            swal({
                title: "Atenção!",
                text: merchant.open ? 'Deseja realmente abrir seu estabelecimento?' : "Deseja realmente fechar seu estabelecimento?",
                type: "warning",
                showCancelButton: true,
                confirmButtonColor: "#DD6B55",
                confirmButtonText: "Sim",
                cancelButtonText: "Cancelar",
                closeOnConfirm: true,
                closeOnCancel: true
            }, function (isConfirm) {
                if (isConfirm) {
                    DeliveryMerchantService.updateOpen(merchant).then(function (response) {
                        $scope.selectedMerchant.open = open;
                    });
                }
            });
        }

        $scope.showModalMerchantPause = function () {
            $scope.modalMerchantPause = $uibModal.open({
                animation: true,
                ariaLabelledBy: 'modal-title-top',
                ariaDescribedBy: 'modal-body-top',
                templateUrl: 'template/modal-merchant-pause.html',
                scope: $scope
            });
        }

        $scope.isMerchantPaused = function () {
            if ($scope.merchantPausedInterval || !$scope.selectedMerchant.pauseAt) {
                return;
            }

            $scope.merchantPausedInterval = setInterval(function () {
                $scope.selectedMerchant.paused = $scope.selectedMerchant.pauseAt > new Date().getTime();
                $scope.$apply();

                if (!$scope.selectedMerchant.paused) {
                    clearInterval($scope.merchantPausedInterval);
                    $scope.merchantPausedInterval = null;
                }
            }, 1000);
        }

        $scope.updatePauseAt = function () {
            if ($scope.selectedMerchant.minutesToPause <= 0) {
                swal("Pausa", "Informe uma pausa maior que 1 minuto.", 'error');
                return;
            }

            DeliveryMerchantService.updatePauseAt($scope.selectedMerchant).then(function (response) {
                $scope.selectedMerchant.pauseAt = response.data.pauseAt;
                $scope.selectedMerchant.paused = true;

                $scope.onCloseModalMerchantPause();
                $scope.isMerchantPaused();
            });
        }

        $scope.clearPauseAt = function () {
            swal({
                title: "Atenção!",
                text: 'Deseja realmente abrir seu estabelecimento?',
                type: "warning",
                showCancelButton: true,
                confirmButtonColor: "#DD6B55",
                confirmButtonText: "Sim",
                cancelButtonText: "Cancelar",
                closeOnConfirm: true,
                closeOnCancel: true
            }, function (isConfirm) {
                if (isConfirm) {
                    var merchant = angular.copy($scope.selectedMerchant);
                    merchant.minutesToPause = 0;

                    DeliveryMerchantService.updatePauseAt(merchant).then(function (response) {
                        $scope.selectedMerchant.pauseAt = null;
                        $scope.selectedMerchant.paused = false;
                    });
                }
            });
        }

        $scope.onCloseModalMerchantPause = function () {
            if ($scope.modalMerchantPause) {
                delete $scope.selectedMerchant.minutesToPause;
                $scope.modalMerchantPause.close();
            }
        };

        $scope.onCloseModalExpired = function () {
            if ($scope.modalExpired) {
                $scope.modalExpired.close();
            }
        };

