materialAdmin.service("TaskService", ['$http', '$setting', function ($http, $setting) {

    var DATE_FORMATS = ['DD/MM/YYYY HH:mm:ss', 'DD/MM/YYYY HH:mm', 'DD/MM/YYYY'];

    var STATUS = ['PENDING', 'LATE', 'DONE', 'CANCELED'];

    this.parseDate = function (value) {
        if (value === null || value === undefined || value === '') {
            return null;
        }

        if (typeof value === 'number') {
            return moment(value);
        }

        var texto = String(value).trim();

        if (/^\d+$/.test(texto)) {
            return moment(parseInt(texto, 10));
        }

        var data = moment(texto, DATE_FORMATS, true);

        if (!data.isValid()) {
            data = moment(texto);
        }

        return data.isValid() ? data : null;
    };

    this.normalize = (task) => {
        var start = this.parseDate(task.startDate);
        var end = this.parseDate(task.endDate);
        var finished = this.parseDate(task.finishedAt);

        if (!end) {
            end = start;
        }

        if (!start) {
            start = end;
        }

        if (start && end && start.isAfter(end)) {
            start = end.clone();
        }

        var status = (task.status || '').toString().toUpperCase();

        if (STATUS.indexOf(status) === -1) {
            if (finished) {
                status = 'DONE';
            } else if (end && end.isBefore(moment())) {
                status = 'LATE';
            } else {
                status = 'PENDING';
            }
        }

        return angular.extend({}, task, {
            status: status,
            startAt: start ? start.toDate() : null,
            endAt: end ? end.toDate() : null,
            finishedAtDate: finished ? finished.toDate() : null
        });
    };

    this.getAll = function (filtro) {
        var request = $http({
            method: "GET",
            url: `${$setting.api}/crm/tasks`,
            params: filtro
        });

        return (request);
    };

    this.getById = function (id) {
        var request = $http({
            method: "GET",
            url: `${$setting.api}/crm/tasks/${id}`
        });

        return (request);
    };

    this.get = (type, id) => {
        var request = $http({
            method: "get",
            url: $setting.api + "/task_rule/" + id,
            params: { "type": type },
        });

        return request;
    };

    this.getCalendar = (startDate, endDate) => {
        return $http({
            method: "GET",
            url: `${$setting.api}/crm/tasks`,
            params: {
                startDate: startDate,
                endDate: endDate,
                viewMode: "CALENDAR"
            }
        });
    };

    this.done = function (id, note) {
        var request = $http({
            method: "POST",
            url: `${$setting.api}/crm/tasks/${id}/done`,
            data: {
                finishedNotes: note
            }
        });

        return (request);
    };

    this.add = (id, taskData) => {
        return $http({
            method: "POST",
            url: `${$setting.api}/crm/cards/${id}/tasks`,
            data: taskData
        });
    };

    this.edit = (taskData) => {
        return $http({
            method: "POST",
            url: $setting.api + "/crm/tasks/" + taskData.id,
            data: {
                name: taskData.name,
                responsibleId: taskData.responsibleId,
                description: taskData.description,
                startDate: taskData.startDate,
                endDate: taskData.endDate,
                notificationBeforeMinutes: taskData.notificationBeforeMinutes,
                participants: taskData.participants
            }
        });
    };

    this.cancel = function (id, note) {
        var request = $http({
            method: "POST",
            url: `${$setting.api}/crm/tasks/${id}/cancel`,
            data: {
                finishedNotes: note
            }
        });

        return (request);
    };
}]);
;



