materialAdmin.service("WaCallWebRTCService", [
    '$uibModal',
    '$interval',
    '$timeout',
    'WaCallHttpService',
    'FileService',
    function ($uibModal, $interval, $timeout, WaCallHttpService, FileService) {

        var self = this;

        this.incomingCalls = [];
        this.activeCall = null;
        this.modalCalls = null;
        this.ringtone = null;
        this.activeCallDurationInterval = null;
        this.disconnectTimeout = null;

        // =====================================================
        // UTILITÁRIOS
        // =====================================================

        this.getRemoteAudio = function () {
            return document.getElementById('remoteAudio');
        };

        this.formatCallDuration = function (totalSegundos) {
            if (typeof formatCallDuration === 'function') {
                return formatCallDuration(totalSegundos);
            }

            var segundos = Math.max(0, Number(totalSegundos) || 0);
            var minutos = Math.floor(segundos / 60);
            var resto = segundos % 60;

            return String(minutos).padStart(2, '0') + ':' +
                String(resto).padStart(2, '0');
        };

        this.processEvent = function (payload) {
            var data;

            try {
                data = typeof payload === 'string'
                    ? JSON.parse(payload)
                    : payload;
            } catch (error) {
                console.error('Evento WebRTC inválido:', error);
                return;
            }

            if (!data || !data.type) {
                return;
            }

            switch (data.type) {
                case 'call_incoming':
                    self.processOffer(data);
                    break;

                case 'call_accepted':
                    self.processAnswer(data);
                    break;

                case 'status':
                    self.processStatus(data);
                    break;

                default:
                    break;
            }
        };

        // =====================================================
        // MODAL
        // =====================================================

        this.showModalCalls = function () {
            if (self.modalCalls) {
                return;
            }

            self.modalCalls = $uibModal.open({
                animation: true,
                ariaLabelledBy: 'modal-title-top',
                ariaDescribedBy: 'modal-body-top',
                templateUrl: 'views/wa-call/modal-calls.html',
                backdrop: 'static',
                keyboard: true,
                windowClass: 'call-modal'
            });

            self.modalCalls.result.finally(function () {
                self.modalCalls = null;
            });
        };

        this.closeModalCalls = function () {
            if (!self.modalCalls) {
                return;
            }

            var modal = self.modalCalls;
            self.modalCalls = null;

            try {
                modal.close();
            } catch (error) {
                // O modal pode já ter sido encerrado.
            }
        };

        // =====================================================
        // TOQUE
        // =====================================================

        this.startRinging = function () {
            if (self.ringtone) {
                return;
            }

            self.ringtone = new Audio('audio/whatsapp_ring.mp3');
            self.ringtone.loop = true;

            var ringtone = self.ringtone;

            ringtone.play().catch(function (error) {
                console.warn('Não foi possível reproduzir o toque:', error);
            });
        };

        this.stopRinging = function () {
            if (!self.ringtone) {
                return;
            }

            self.ringtone.pause();
            self.ringtone.currentTime = 0;
            self.ringtone = null;
        };

        // =====================================================
        // CHAMADAS RECEBIDAS
        // =====================================================

        this.processOffer = function (callData) {
            if (!callData || !callData.callId) {
                return;
            }

            var incomingCall = self.incomingCalls.find(function (call) {
                return call.callId === callData.callId;
            });

            if (!incomingCall) {
                self.incomingCalls.push(callData);
            }

            self.startRinging();
            self.showModalCalls();
        };

        this.updateStatusIncomingCall = function (callData) {
            var call = self.incomingCalls.find(function (item) {
                return item.callId === callData.callId;
            });

            if (!call) {
                return;
            }

            call.status = callData.status;
            call.agentName = callData.agentName;

            $timeout(function () {
                self.removeCall(call);
            }, 3000);
        };

        this.removeCall = function (call) {
            if (!call) {
                return;
            }

            self.incomingCalls = self.incomingCalls.filter(function (item) {
                return item.callId !== call.callId;
            });

            if (!self.activeCall && self.incomingCalls.length === 0) {
                self.stopRinging();
                self.closeModalCalls();
            }
        };

        this.rejectAllIncomingCalls = function () {
            self.stopRinging();
            self.incomingCalls = [];
        };

        // =====================================================
        // CHAMADA ATIVA E STATUS
        // =====================================================

        this.setActiveCall = function (call) {
            if (!call) {
                return;
            }

            self.activeCall = call;

            if (typeof call.micEnabled === 'undefined') {
                call.micEnabled = true;
            }

            self.rejectAllIncomingCalls();
        };

        this.updateStatusActiveCall = function (status) {
            if (!self.activeCall) {
                return;
            }

            self.activeCall.status = status;

            if (status === 'ACCEPTED') {
                self.stopRinging();
                self.activeCall.callDuration = 0;
                self.activeCall.callDurationStr =
                    self.formatCallDuration(0);

                if (self.activeCallDurationInterval) {
                    $interval.cancel(self.activeCallDurationInterval);
                }

                self.activeCallDurationInterval = $interval(function () {
                    if (!self.activeCall) {
                        return;
                    }

                    self.activeCall.callDuration =
                        (self.activeCall.callDuration || 0) + 1;

                    self.activeCall.callDurationStr =
                        self.formatCallDuration(self.activeCall.callDuration);
                }, 1000);

                self.closeModalCalls();
            }
        };

        this.processStatus = function (callData) {
            if (!callData) {
                return;
            }

            switch (callData.status) {
                case 'RINGING':
                case 'ACCEPTED':
                    if (
                        self.activeCall &&
                        (!callData.callId ||
                            self.activeCall.callId === callData.callId)
                    ) {
                        self.updateStatusActiveCall(callData.status);
                    }
                    break;

                case 'REJECTED':
                case 'FAILED':
                case 'COMPLETED':
                    if (
                        self.activeCall &&
                        self.activeCall.callId === callData.callId
                    ) {
                        self.clearActiveCall(callData.status);
                    } else {
                        self.updateStatusIncomingCall(callData);
                    }
                    break;

                case 'ACCEPTED_OTHER_AGENT':
                    self.updateStatusIncomingCall(callData);
                    break;

                default:
                    break;
            }
        };

        this.processAnswer = function (callData) {
            if (!self.activeCall || !self.activeCall.pc || !callData) {
                return;
            }

            if (callData.callId && self.activeCall.callId &&
                callData.callId !== self.activeCall.callId) {
                return;
            }

            if (!callData.sdpAnswer) {
                console.error('Resposta WebRTC sem SDP.');
                return;
            }

            self.activeCall.pc.setRemoteDescription({
                type: 'answer',
                sdp: callData.sdpAnswer
            }).then(function () {
                if (callData.status) {
                    self.updateStatusActiveCall(callData.status);
                }
            }).catch(function (error) {
                console.error('Erro ao aplicar resposta SDP:', error);
                self.clearActiveCall('FAILED');
            });
        };

        // =====================================================
        // ENCERRAMENTO
        // =====================================================

        this.clearActiveCall = function (status) {
            self.stopRinging();

            if (self.disconnectTimeout) {
                $timeout.cancel(self.disconnectTimeout);
                self.disconnectTimeout = null;
            }

            if (self.activeCallDurationInterval) {
                $interval.cancel(self.activeCallDurationInterval);
                self.activeCallDurationInterval = null;
            }

            var call = self.activeCall;

            if (!call) {
                self.closeModalCalls();
                return;
            }

            if (status) {
                call.status = status;
            }

            // A gravação usa o objeto call capturado, mesmo após limpar
            // self.activeCall.
            if (call.mediaRecorder &&
                call.mediaRecorder.state !== 'inactive') {
                try {
                    call.mediaRecorder.stop();
                } catch (error) {
                    console.error('Erro ao parar gravação:', error);
                }
            }

            if (call.localStream) {
                call.localStream.getTracks().forEach(function (track) {
                    track.stop();
                });
            }

            if (call.pc) {
                call.pc.ontrack = null;
                call.pc.onconnectionstatechange = null;
                call.pc.oniceconnectionstatechange = null;

                call.pc.getSenders().forEach(function (sender) {
                    if (sender.track) {
                        sender.track.stop();
                    }
                });

                call.pc.close();
                call.pc = null;
            }

            var remoteAudio = self.getRemoteAudio();

            if (remoteAudio) {
                remoteAudio.pause();
                remoteAudio.srcObject = null;
            }

            self.activeCall = null;
            self.closeModalCalls();
        };

        this.terminateActiveCall = function () {
            var call = self.activeCall;

            if (!call) {
                return;
            }

            var payload = {
                callId: call.callId,
                ticketId: call.ticketId
            };

            WaCallHttpService.terminate(payload)
                .then(function () {
                    self.clearActiveCall('COMPLETED');
                })
                .catch(function (error) {
                    console.error('Falha ao encerrar chamada:', error);
                });
        };

        // =====================================================
        // MONITORAMENTO DA CONEXÃO
        // =====================================================

        this.monitorConnection = function (call) {
            if (!call || !call.pc) {
                return;
            }

            call.pc.onconnectionstatechange = function () {
                if (!call.pc || self.activeCall !== call) {
                    return;
                }

                var state = call.pc.connectionState;

                if (state === 'connected') {
                    self.stopRinging();
                } else if (state === 'failed') {
                    self.handleConnectionDrop(call, 'FAILED');
                } else if (state === 'closed') {
                    self.handleConnectionDrop(call, 'COMPLETED');
                }
            };

            call.pc.oniceconnectionstatechange = function () {
                if (!call.pc || self.activeCall !== call) {
                    return;
                }

                var state = call.pc.iceConnectionState;

                if (state === 'connected' || state === 'completed') {
                    if (self.disconnectTimeout) {
                        $timeout.cancel(self.disconnectTimeout);
                        self.disconnectTimeout = null;
                    }

                    self.stopRinging();
                } else if (state === 'failed') {
                    self.handleConnectionDrop(call, 'FAILED');
                } else if (state === 'disconnected') {
                    if (self.disconnectTimeout) {
                        $timeout.cancel(self.disconnectTimeout);
                    }

                    self.disconnectTimeout = $timeout(function () {
                        self.disconnectTimeout = null;

                        if (
                            call.pc &&
                            self.activeCall === call &&
                            (
                                call.pc.iceConnectionState === 'disconnected' ||
                                call.pc.iceConnectionState === 'failed'
                            )
                        ) {
                            self.handleConnectionDrop(call, 'COMPLETED');
                        }
                    }, 5000);
                }
            };
        };

        this.handleConnectionDrop = function (call, status) {
            if (!call || self.activeCall !== call) {
                return;
            }

            if (self.disconnectTimeout) {
                $timeout.cancel(self.disconnectTimeout);
                self.disconnectTimeout = null;
            }

            self.clearActiveCall(status);
        };

        // =====================================================
        // ICE
        // =====================================================

        this.waitForIceGatheringComplete = function (pc) {
            if (pc.iceGatheringState === 'complete') {
                return Promise.resolve();
            }

            return new Promise(function (resolve, reject) {
                var finished = false;

                var timeout = setTimeout(function () {
                    finish(new Error('Tempo limite ao reunir candidatos ICE.'));
                }, 15000);

                function cleanup() {
                    clearTimeout(timeout);
                    pc.removeEventListener(
                        'icegatheringstatechange',
                        checkState
                    );
                }

                function finish(error) {
                    if (finished) {
                        return;
                    }

                    finished = true;
                    cleanup();

                    if (error) {
                        reject(error);
                    } else {
                        resolve();
                    }
                }

                function checkState() {
                    if (pc.iceGatheringState === 'complete') {
                        finish();
                    }
                }

                pc.addEventListener(
                    'icegatheringstatechange',
                    checkState
                );

                checkState();
            });
        };

        // =====================================================
        // ACEITAR CHAMADA RECEBIDA
        // =====================================================

        this.acceptCall = async function (call) {
            if (!call || !call.sdpOffer || !call.callId) {
                console.error('Chamada recebida sem callId ou SDP offer.');
                return;
            }

            if (self.activeCall) {
                console.warn('Já existe uma chamada ativa.');
                return;
            }

            try {
                call.pc = new RTCPeerConnection();

                self.setActiveCall(call);
                self.monitorConnection(call);

                var remoteAudio = self.getRemoteAudio();

                call.pc.ontrack = function (event) {
                    call.remoteStream =
                        event.streams && event.streams[0];

                    if (remoteAudio && call.remoteStream) {
                        remoteAudio.srcObject = call.remoteStream;

                        remoteAudio.play().catch(function (error) {
                            console.warn(
                                'Reprodução de áudio bloqueada:',
                                error
                            );
                        });
                    }
                };

                call.localStream =
                    await navigator.mediaDevices.getUserMedia({
                        audio: true,
                        video: false
                    });

                call.localStream.getTracks().forEach(function (track) {
                    call.pc.addTrack(track, call.localStream);
                });

                await call.pc.setRemoteDescription({
                    type: 'offer',
                    sdp: call.sdpOffer
                });

                var answer = await call.pc.createAnswer();

                await call.pc.setLocalDescription(answer);
                await self.waitForIceGatheringComplete(call.pc);

                call.sdpAnswer = call.pc.localDescription.sdp;
                call.status = 'SEND_ACCEPT';

                var payload = {
                    callId: call.callId,
                    ticketId: call.ticketId,
                    sdp: call.sdpAnswer
                };

                await WaCallHttpService.accept(payload);

                if (self.activeCall === call) {
                    self.updateStatusActiveCall('ACCEPTED');
                }
            } catch (error) {
                console.error('Falha ao aceitar chamada:', error);

                if (self.activeCall === call) {
                    self.clearActiveCall('FAILED');
                } else {
                    if (call.localStream) {
                        call.localStream.getTracks().forEach(function (track) {
                            track.stop();
                        });
                    }

                    if (call.pc) {
                        call.pc.close();
                        call.pc = null;
                    }
                }
            }
        };

        // =====================================================
        // RECUSAR CHAMADA
        // =====================================================

        this.rejectCall = function (call) {
            if (!call || !call.callId) {
                return;
            }

            var payload = {
                callId: call.callId,
                ticketId: call.ticketId
            };

            WaCallHttpService.reject(payload)
                .then(function () {
                    self.removeCall(call);
                })
                .catch(function (error) {
                    console.error('Falha ao recusar chamada:', error);
                });
        };

        // =====================================================
        // INICIAR CHAMADA
        // =====================================================

        this.dial = async function (
            ticketId,
            botNumber,
            contactNumber,
            contactName,
            contactPhoto
        ) {
            if (self.activeCall) {
                console.warn('Já existe uma chamada ativa.');
                return;
            }

            var call = {};
            var pc = null;

            try {
                pc = new RTCPeerConnection();

                call.ticketId = ticketId;
                call.botNumber = botNumber;
                call.contactNumber = contactNumber;
                call.contactName = contactName;
                call.contactPhoto = contactPhoto;
                call.pc = pc;
                call.status = 'SEND_CONNECT';
                call.micEnabled = true;

                var remoteAudio = self.getRemoteAudio();

                pc.ontrack = function (event) {
                    call.remoteStream =
                        event.streams && event.streams[0];

                    if (remoteAudio && call.remoteStream) {
                        remoteAudio.srcObject = call.remoteStream;

                        remoteAudio.play().catch(function (error) {
                            console.warn(
                                'Reprodução de áudio bloqueada:',
                                error
                            );
                        });
                    }
                };

                call.localStream =
                    await navigator.mediaDevices.getUserMedia({
                        audio: true,
                        video: false
                    });

                call.localStream.getTracks().forEach(function (track) {
                    pc.addTrack(track, call.localStream);
                });

                self.setActiveCall(call);
                self.monitorConnection(call);

                var offer = await pc.createOffer();
                await pc.setLocalDescription(offer);
                await self.waitForIceGatheringComplete(pc);

                var payload = {
                    ticketId: ticketId,
                    sdp: pc.localDescription.sdp
                };

                var response = await WaCallHttpService.dial(payload);

                if (!response || !response.data || !response.data.callId) {
                    throw new Error('A API não retornou o identificador da chamada.');
                }

                call.callId = response.data.callId;

                if (self.activeCall === call) {
                    self.startRinging();
                    self.showModalCalls();
                }
            } catch (error) {
                console.error('Falha ao iniciar chamada:', error);

                if (self.activeCall === call) {
                    self.clearActiveCall('FAILED');
                } else {
                    if (call.localStream) {
                        call.localStream.getTracks().forEach(function (track) {
                            track.stop();
                        });
                    }

                    if (pc) {
                        pc.close();
                    }
                }
            }
        };

        // =====================================================
        // MICROFONE
        // =====================================================

        this.updateMicStatus = function () {
            var call = self.activeCall;

            if (!call || !call.pc) {
                return;
            }

            call.micEnabled = !call.micEnabled;

            call.pc.getSenders().forEach(function (sender) {
                if (sender.track && sender.track.kind === 'audio') {
                    sender.track.enabled = call.micEnabled;
                }
            });
        };

        // =====================================================
        // GRAVAÇÃO
        // =====================================================

        this.startRecord = function () {
            var call = self.activeCall;

            if (
                !call ||
                !call.localStream ||
                !call.remoteStream ||
                typeof MediaRecorder === 'undefined'
            ) {
                return false;
            }

            try {
                var audioContext = new AudioContext();
                var destination = audioContext.createMediaStreamDestination();

                var localSource =
                    audioContext.createMediaStreamSource(call.localStream);

                var remoteSource =
                    audioContext.createMediaStreamSource(call.remoteStream);

                localSource.connect(destination);
                remoteSource.connect(destination);

                var mimeType = 'audio/webm';

                if (
                    MediaRecorder.isTypeSupported &&
                    !MediaRecorder.isTypeSupported(mimeType)
                ) {
                    mimeType = '';
                }

                call.audioContext = audioContext;
                call.recordedChunks = [];

                call.mediaRecorder = mimeType
                    ? new MediaRecorder(destination.stream, {
                        mimeType: mimeType
                    })
                    : new MediaRecorder(destination.stream);

                call.mediaRecorder.addEventListener(
                    'dataavailable',
                    function (event) {
                        if (event.data && event.data.size > 0) {
                            call.recordedChunks.push(event.data);
                        }
                    }
                );

                call.mediaRecorder.addEventListener('stop', function () {
                    self.uploadRecord(call);
                });

                call.mediaRecorder.start();

                return true;
            } catch (error) {
                console.error('Erro ao iniciar gravação:', error);
                return false;
            }
        };

        this.uploadRecord = function (call) {
            if (
                !call ||
                !call.recordedChunks ||
                call.recordedChunks.length === 0
            ) {
                return;
            }

            var blob = new Blob(call.recordedChunks, {
                type: 'audio/webm'
            });

            FileService.insertBlob(blob, 'call_recording.webm')
                .then(function (response) {
                    if (!response || !response.data || !response.data.url) {
                        throw new Error('O upload não retornou a URL da gravação.');
                    }

                    if (!call.callId) {
                        console.warn(
                            'Gravação enviada, mas a chamada não possui callId.'
                        );
                        return;
                    }

                    return WaCallHttpService.updateRecordingLink({
                        callId: call.callId,
                        url: response.data.url
                    }).then(function () {
                        call.status = 'RECORDING_FINISHED';
                    });
                })
                .catch(function (error) {
                    console.error('Erro ao enviar gravação:', error);
                })
                .finally(function () {
                    if (call.audioContext) {
                        call.audioContext.close().catch(function () {});
                        call.audioContext = null;
                    }
                });
        };
    }
]);


