materialAdmin.service("FileService", function ($http) {

    var API = "https://banco-arquivo.n3bot.com.br";

    // ==========================================================
    // URL DA API
    // ==========================================================

    this.getUrl = function () {
        return API;
    };


    // ==========================================================
    // UPLOAD DE BLOB
    // ==========================================================

    this.insertBlob = function (blob, name, fixed, ignoreFileSize) {

        ignoreFileSize = ignoreFileSize || false;

        if (!blob) {
            return;
        }

        if (!ignoreFileSize && !validateSize(blob)) {
            return;
        }

        if (!validateBlobMinimumSize(blob)) {
            return;
        }

        var formData = new FormData();

        formData.append(
            "file",
            blob,
            name
        );

        formData.append(
            "fixed",
            fixed || false
        );

        return $http({
            method: "POST",
            url: API + "/upload",
            data: formData,
            headers: {
                "Content-Type": undefined
            },
            transformRequest: angular.identity
        });
    };


    // ==========================================================
    // UPLOAD BASE64
    // ==========================================================

    this.insertBase64 = function (
        base64,
        name,
        fixed,
        ignoreFileSize
    ) {

        ignoreFileSize = ignoreFileSize || false;

        var blob = base64ToBlob(base64);

        if (!blob) {
            return;
        }

        return this.insertBlob(
            blob,
            name,
            fixed,
            ignoreFileSize
        );
    };


    // ==========================================================
    // FILE LIST -> BASE64
    // ==========================================================

    this.fileListToBase64 = async function (fileList) {

        function getBase64(file) {

            var reader = new FileReader();

            return new Promise(function (resolve, reject) {

                reader.onload = function (event) {
                    resolve(event.target.result);
                };

                reader.onerror = function (error) {
                    reject(error);
                };

                reader.readAsDataURL(file);
            });
        }

        var promises = [];

        for (var i = 0; i < fileList.length; i++) {

            promises.push(
                getBase64(fileList[i])
            );
        }

        return Promise.all(promises);
    };


    // ==========================================================
    // LISTAR ARQUIVOS
    // ==========================================================

    this.getAll = function (params) {

        return $http({
            method: "GET",
            url: API,
            params: params || {}
        });
    };


    // ==========================================================
    // EXCLUIR UM ARQUIVO
    // ==========================================================

    this.delete = function (id) {

        return $http({
            method: "DELETE",
            url: API + "/" + id
        });
    };


    // ==========================================================
    // EXCLUIR VÁRIOS
    // ==========================================================

    this.deleteMany = function (ids) {

        return $http({
            method: "DELETE",
            url: API,
            data: {
                ids: ids
            },
            headers: {
                "Content-Type": "application/json"
            }
        });
    };


    // ==========================================================
    // CRIAR PASTA
    // ==========================================================

    this.createFolder = function (data) {

        return $http({
            method: "POST",
            url: API + "/pastas",
            data: data
        });
    };


    // ==========================================================
    // MOVER ARQUIVOS
    // ==========================================================

    this.move = function (ids, pastaId) {

        return $http({
            method: "PUT",
            url: API + "/mover",
            data: {
                ids: ids,
                pastaId: pastaId
            }
        });
    };


    // ==========================================================
    // COMPARTILHAMENTO
    // ==========================================================

    this.updateSharing = function (id, compartilhado) {

        return $http({
            method: "PUT",
            url: API + "/" + id + "/compartilhamento",
            data: {
                compartilhado: compartilhado
            }
        });
    };


    // ==========================================================
    // CONVERTER BASE64 PARA BLOB
    // ==========================================================

    function base64ToBlob(dataURI) {

        if (!dataURI) {
            return null;
        }

        var splitDataURI =
            dataURI.split(",");

        if (splitDataURI.length < 2) {
            return null;
        }

        var header =
            splitDataURI[0];

        var data =
            splitDataURI[1];

        var byteString;

        if (header.indexOf("base64") >= 0) {

            byteString = atob(data);

        } else {

            byteString =
                decodeURIComponent(data);
        }

        var mimeString = "application/octet-stream";

        if (header.indexOf(":") >= 0) {

            mimeString =
                header
                    .split(":")[1]
                    .split(";")[0];
        }

        var ia =
            new Uint8Array(
                byteString.length
            );

        for (
            var i = 0;
            i < byteString.length;
            i++
        ) {

            ia[i] =
                byteString.charCodeAt(i);
        }

        return new Blob(
            [ia],
            {
                type: mimeString
            }
        );
    }


    // ==========================================================
    // VALIDAR TAMANHO
    // ==========================================================

    function validateSize(file) {

        if (file.size > 52428800) {

            swal(
                "Ops!",
                "Envie um arquivo com no máximo 50MB.",
                "error"
            );

            return false;
        }

        return true;
    }


    // ==========================================================
    // TAMANHO MÍNIMO
    // ==========================================================

    function validateBlobMinimumSize(blob) {

        if (blob.size <= 1024) {

            swal(
                "Ops!",
                "Arquivo vazio. Envie um arquivo maior que 1KB.",
                "error"
            );

            return false;
        }

        return true;
    }

});
materialAdmin.controller('AtendimentosController', [
    '$scope',
    '$location',
    '$timeout',
    'AtendimentoService',
    function (
        $scope,
        $location,
        $timeout,
        AtendimentoService
    ) {

        var vm = this;


        // =====================================================
        // VARIÁVEIS
        // =====================================================

        vm.ativos = [];
        vm.pendentes = [];
        vm.potenciais = [];

        vm.aba = 'ativos';

        vm.pesquisa = '';

        vm.carregando = false;

        vm.erro = '';


        // =====================================================
        // EMPRESA
        // =====================================================

        vm.empresaId =
            AtendimentoService.getEmpresaId();


        // =====================================================
        // CARREGAR ATIVOS
        // =====================================================

        vm.carregarAtivos = function () {

            return AtendimentoService.ativosNormalizados()

                .then(function (dados) {

                    vm.ativos = dados || [];



                    return vm.ativos;

                })

                .catch(function (error) {

                    console.error(
                        '❌ Erro ao carregar atendimentos ativos:',
                        error
                    );

                    vm.ativos = [];

                    return [];
                });
        };


        // =====================================================
        // CARREGAR PENDENTES
        // =====================================================

        vm.carregarPendentes = function () {

            return AtendimentoService.pendentesNormalizados()

                .then(function (dados) {

                    vm.pendentes = dados || [];



                    return vm.pendentes;

                })

                .catch(function (error) {

                    console.error(
                        '❌ Erro ao carregar atendimentos pendentes:',
                        error
                    );

                    vm.pendentes = [];

                    return [];
                });
        };


        // =====================================================
        // CARREGAR POTENCIAIS
        // =====================================================

        vm.carregarPotenciais = function () {

            return AtendimentoService.potenciaisNormalizados()

                .then(function (dados) {

                    vm.potenciais = dados || [];



                    return vm.potenciais;

                })

                .catch(function (error) {

                    console.error(
                        '❌ Erro ao carregar atendimentos potenciais:',
                        error
                    );

                    vm.potenciais = [];

                    return [];
                });
        };


        // =====================================================
        // CARREGAR TUDO
        // =====================================================

        vm.carregarTodos = function () {

            vm.carregando = true;

            vm.erro = '';

            /*
             * AngularJS antigo não precisa depender de
             * Promise.all(). Fazemos as três requisições
             * independentemente.
             */

            return $scope.$evalAsync(function () {

                vm.carregarAtivos();
                vm.carregarPendentes();
                vm.carregarPotenciais();

            });

        };


        // =====================================================
        // RECARREGAR
        // =====================================================

        vm.recarregar = function () {

            vm.carregando = true;

            vm.erro = '';

            var contador = 0;

            function finalizado() {

                contador++;

                if (contador >= 3) {

                    $scope.$evalAsync(function () {

                        vm.carregando = false;

                    });
                }
            }

            vm.carregarAtivos()
                .finally(finalizado);

            vm.carregarPendentes()
                .finally(finalizado);

            vm.carregarPotenciais()
                .finally(finalizado);
        };


        // =====================================================
        // TROCAR ABA
        // =====================================================

        vm.selecionarAba = function (aba) {

            if (
                aba !== 'ativos' &&
                aba !== 'pendentes' &&
                aba !== 'potenciais'
            ) {
                return;
            }

            vm.aba = aba;

            vm.pesquisa = '';

        };


        // =====================================================
        // OBTER LISTA DA ABA ATUAL
        // =====================================================

        vm.getListaAtual = function () {

            if (vm.aba === 'pendentes') {
                return vm.pendentes;
            }

            if (vm.aba === 'potenciais') {
                return vm.potenciais;
            }

            return vm.ativos;
        };


        // =====================================================
        // QUANTIDADES
        // =====================================================

        vm.totalAtivos = function () {

            return vm.ativos.length;

        };


        vm.totalPendentes = function () {

            return vm.pendentes.length;

        };


        vm.totalPotenciais = function () {

            return vm.potenciais.length;

        };


        vm.total = function () {

            return (
                vm.ativos.length +
                vm.pendentes.length +
                vm.potenciais.length
            );

        };


        // =====================================================
        // FILTRO DE PESQUISA
        // =====================================================

        vm.filtrar = function (atendimento) {

            if (!atendimento) {
                return false;
            }

            var pesquisa =
                String(
                    vm.pesquisa || ''
                )
                .toLowerCase()
                .trim();

            if (!pesquisa) {
                return true;
            }

            var nome =
                String(
                    atendimento.nome || ''
                )
                .toLowerCase();

            var numero =
                String(
                    atendimento.numero || ''
                )
                .toLowerCase();

            var telefone =
                String(
                    atendimento.telefone || ''
                )
                .toLowerCase();

            var ticket =
                String(
                    atendimento.ticket || ''
                )
                .toLowerCase();

            var cpf =
                String(
                    atendimento.cpf || ''
                )
                .toLowerCase();

            return (
                nome.indexOf(pesquisa) !== -1 ||
                numero.indexOf(pesquisa) !== -1 ||
                telefone.indexOf(pesquisa) !== -1 ||
                ticket.indexOf(pesquisa) !== -1 ||
                cpf.indexOf(pesquisa) !== -1
            );
        };


        // =====================================================
        // ABRIR ATENDIMENTO
        // =====================================================

        vm.abrir = function (atendimento) {

            if (!atendimento) {
                return;
            }

            var id =
                atendimento.id ||
                atendimento.numero ||
                atendimento.telefone;

            if (!id) {

                console.error(
                    '❌ Atendimento sem ID:',
                    atendimento
                );

                return;
            }



            /*
             * A rota continua sendo:
             *
             * /atendimentos/chat/:id
             */

            $location.path(
                '/atendimentos/chat/' +
                encodeURIComponent(
                    String(id)
                )
            );
        };


        // =====================================================
        // INICIAL DO NOME
        // =====================================================

        vm.inicial = function (nome) {

            if (!nome) {
                return '?';
            }

            nome =
                String(nome)
                    .trim();

            if (!nome) {
                return '?';
            }

            /*
             * Pega a primeira letra.
             */

            return nome
                .charAt(0)
                .toUpperCase();
        };


        // =====================================================
        // NOME PARA EXIBIÇÃO
        // =====================================================

        vm.nomeExibicao = function (atendimento) {

            if (!atendimento) {
                return 'Sem identificação';
            }

            return (
                atendimento.nome ||
                atendimento.nomeCliente ||
                atendimento.clienteNome ||
                atendimento.numero ||
                atendimento.telefone ||
                'Sem identificação'
            );
        };


        // =====================================================
        // NÚMERO PARA EXIBIÇÃO
        // =====================================================

        vm.numeroExibicao = function (atendimento) {

            if (!atendimento) {
                return '';
            }

            return (
                atendimento.numero ||
                atendimento.telefone ||
                atendimento.whatsapp ||
                ''
            );
        };


        // =====================================================
        // STATUS
        // =====================================================

        vm.statusExibicao = function (atendimento) {

            if (!atendimento) {
                return '';
            }

            return (
                atendimento.status ||
                ''
            );
        };


        // =====================================================
        // CONTAGEM DE NÃO LIDAS
        // =====================================================

        vm.naoVisualizadas = function (atendimento) {

            if (!atendimento) {
                return 0;
            }

            return Number(
                atendimento.mensagensNaoVisualizadas || 0
            );
        };


        // =====================================================
        // INICIALIZAÇÃO
        // =====================================================



        if (!vm.empresaId) {

            console.error(
                '❌ Nenhuma empresa encontrada para o usuário.'
            );

            vm.erro =
                'Empresa não identificada.';

        } else {

            vm.recarregar();

        }


        // =====================================================
        // LIMPEZA
        // =====================================================

        $scope.$on(
            '$destroy',
            function () {



            }
        );

    }
]);

materialAdmin.controller('AtendimentoTemplateController', function ($scope, $sce, FileService) {

    $scope.trustSrc = function (src) {
        return $sce.trustAsResourceUrl(src);
    };

    $scope.onInit = () => {
        $scope.previaTemplate = null;
        $scope.previaTemplateGeral = null;

        $scope.templates.forEach(t => {
            t.languages.forEach(l => {
                l.name = t.name;
                $scope.prepararComponentes(l.components);
            })
        });

        angular.element("#image-input")
            .on('change.bs.fileinput',
                (event, data) => {
                    $scope.uploadFile(data);
                });

        angular.element("#image-input")
            .on('clear.bs.fileinput',
                (event) => {
                    $scope.uploadFile(null);
                });
    }

    $scope.config = {
        whatsappTemplateId: 0
    }

    $scope.prepararComponentes = (components) => {

        if (components && components.length > 0) {
            components.forEach(component => {
                if (!component.parameters) {
                    component.parameters = [];
                }

                let qtParameters = 0;

                if (component.type == 'BUTTONS') {
                    component.buttons.forEach(b => {
                        if (b.type == 'URL') {
                            qtParameters = $scope.getStringParameters(b.url);

                            for (let i = 0; i < qtParameters; i++) {
                                if (!b.parameters) { b.parameters = [] }

                                if (!b.parameters[i]) {
                                    b.parameters[i] = { type: 'TEXTO', text: '', parameter: i + 1 };
                                } else if (b.parameters[i].type == 'CONTATO_INFORMACAO' || b.parameters[i].contatoInformacaoId) {
                                    b.parameters[i].type = 'CONTATO_INFORMACAO';
                                    if ($scope.atendimentoSelecionado && $scope.atendimentoSelecionado.informacoes && $scope.atendimentoSelecionado.informacoes.usuario && $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais) {
                                        let informacao = null;
                                        if (b.parameters[i].contatoInformacaoId == 1) {
                                            informacao = { valorOriginal: $scope.atendimentoSelecionado.informacoes.usuario.usuarioNome }
                                        } else {
                                            informacao = $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais.find(ia => ia.contatoInformacaoId == b.parameters[i].contatoInformacaoId);
                                        }

                                        if (informacao) {
                                            b.parameters[i].text = informacao.valorOriginal;
                                        }
                                    }
                                }
                            }
                        } else if (b.type == 'QUICK_REPLY') {
                            if (!b.parameters) { b.parameters = [] }

                            if (!b.parameters[0]) {
                                b.parameters[0] = { type: 'TEXTO', text: b.text };
                            }
                        }
                    })
                } else if (component.format == 'IMAGE' || component.format == 'DOCUMENT' || component.format == 'VIDEO') {
                    if (component.parameters && component.parameters.length > 0) {
                        component.parameters[0].type = component.format;
                        component.parameters[0].url = `url(${component.parameters[0].text})`;
                        component.parameters[0].parameter = 1;
                    }
                } else {
                    qtParameters = $scope.getStringParameters(component.text);

                    for (let i = 0; i < qtParameters; i++) {
                        if (!component.parameters[i]) {
                            component.parameters[i] = { type: 'TEXTO', text: '', parameter: i + 1 };
                        } else if (component.parameters[i].type == 'CONTATO_INFORMACAO' || component.parameters[i].contatoInformacaoId) {
                            component.parameters[i].type = 'CONTATO_INFORMACAO';
                            if ($scope.atendimentoSelecionado && $scope.atendimentoSelecionado.informacoes && $scope.atendimentoSelecionado.informacoes.usuario && $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais) {
                                let informacao = null;
                                if (component.parameters[i].contatoInformacaoId == 1) {
                                    informacao = { valorOriginal: $scope.atendimentoSelecionado.informacoes.usuario.usuarioNome }
                                } else {
                                    informacao = $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais.find(ia => ia.contatoInformacaoId == component.parameters[i].contatoInformacaoId);
                                }

                                if (informacao) {
                                    component.parameters[i].text = informacao.valorOriginal;
                                }
                            }
                        }
                    }
                }
            })
        }
    }

    $scope.visualizarTemplateById = (id) => {
        let template = null;
        $scope.templates.forEach(tg => tg.languages.forEach(t => { if (t.whatsappTemplateId == id) template = t; }));
        $scope.visualizarTemplate(template, true);
    }

    $scope.visualizarTemplate = (template, configuracaoGeral) => {
        $scope.previaTemplate = template;

        if (configuracaoGeral) {
            $scope.previaTemplateGeral = template;
        }

        let isHeaderCustomizable = false;
        let isBodyCustomizable = false;
        let isButtonsCustomizable = false;

        $scope.previaTemplate.components.forEach(component => {
            if (component.type == 'HEADER') {
                $scope.previaTemplate.headerType = component.format;
                let isMediaHeader = component.format == 'IMAGE'
                    || component.format == 'VIDEO'
                    || component.format == 'DOCUMENT';

                isHeaderCustomizable = ((component.format == 'TEXT' && $scope.getStringParameters(component.text) > 0) || isMediaHeader) || isHeaderCustomizable;

                if (isMediaHeader && component.parameters && component.parameters.length > 0) {
                    $scope.selectHeaderFile(component, component.parameters[0].text);
                } else {
                    $scope.updateFileInput(null);
                }
            }

            isBodyCustomizable = (component.type == 'BODY' && $scope.getStringParameters(component.text) > 0) || isBodyCustomizable;


            if (component.type == 'BUTTONS') {
                component.buttons.forEach(button => {
                    isButtonsCustomizable = button.type == 'QUICK_REPLY' || (button.type == 'URL' && $scope.getStringParameters(button.url) > 0) || isButtonsCustomizable
                });
            }

        })

        $scope.previaTemplate.isCustomizable = isHeaderCustomizable || isBodyCustomizable || isButtonsCustomizable;
        $scope.previaTemplate.isHeaderCustomizable = isHeaderCustomizable;
        $scope.previaTemplate.isBodyCustomizable = isBodyCustomizable;
        $scope.previaTemplate.isButtonsCustomizable = isButtonsCustomizable;

        updateComponentsAfterRequest();
    }

    $scope.getStringParameters = (text) => {
        if (text) {
            var matches = text.match(/{{[0-9]+}}/gm);
            return matches ? matches.length : 0;
        }
        return 0;
    }

    $scope.renderComponentText = (component) => {
        let text = component.text || "";

        if (component.parameters) {
            component.parameters.forEach(p => {
                if (p.text) {
                    text = text.replace(`{{${p.parameter}}}`, p.text);
                }
            });
        }

        return $scope.tratarTexto(text);
    }

    $scope.processarComponentes = (components) => {
        if (components && components.length > 0) {
            components.forEach(component => {
                $scope.processarParametros(component.parameters);
            })
        }
    }

    $scope.processarParametros = (parameters) => {
        if (parameters && parameters.length > 0) {
            parameters.forEach((parameterConfig, i) => {
                parameterConfig.parameter = i + 1;
            })
        }
    }

    $scope.uploadFile = (file) => {
        let component = null;

        file = file ? file[0] : null;

        $scope.previaTemplate.components.forEach(c => {
            if (c.type == 'HEADER' && (c.format == 'IMAGE' || c.format == 'VIDEO' || c.format == 'DOCUMENT')) {
                component = c;
            }
        })

        if (file) {
            if (component.format == 'DOCUMENT') {
                if (!file.type.match("pdf")) {
                    $scope.updateFileInput(null)
                    return swal("Ops!", "Apenas arquivos PDF são aceitos para esse tipo de customização", "error");
                }
            }

            if (component.format == 'IMAGE') {
                if (!file.type.match("image/jpeg|image/png")) {
                    $scope.updateFileInput(null)
                    return swal("Ops!", "Apenas arquivos de imagem (JPG ou PNG) são aceitos para esse tipo de customização", "error");
                }
            }

            if (component.format == 'VIDEO') {
                if (!file.type.match("video/mp4|video/3gpp")) {
                    $scope.updateFileInput(null)
                    return swal("Ops!", "Apenas arquivos de vídeo (MP4 ou 3GP) são aceitos para esse tipo de customização", "error");
                }
            }

            var reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = function () {
                FileService.insertBase64(reader.result, file.name).then(function (response) {
                    $scope.selectHeaderFile(component, response.data.url);
                });
            };
        } else {
            $scope.selectHeaderFile(component, null);
        }
    }

    $scope.selectHeaderFile = (component, url) => {
        if (component) {
            if (!component.parameters) {
                component.parameters = [];
            }

            if (component.parameters[0]) {
                component.parameters[0].text = url;
                component.parameters[0].url = url ? `url(${url})` : null;
            } else {
                component.parameters = [{ parameter: 1, text: url, type: component.format, componentType: component.type, url: url ? `url(${url})` : null }];
            }
        }

        $scope.updateFileInput(url);
    }

    $scope.updateFileInput = (url) => {
        if (url) {
            $(`#image-input img`).attr("src", url);
            $(`#image-input span.fileinput-new`).hide();
            $(`#image-input span.fileinput-exists`).show();
            $(`#image-input a.fileinput-exists`).show().css({ display: "block" });
        } else {
            $(`#image-input img`).removeAttr("src");
            $(`#image-input span.fileinput-new`).show();
            $(`#image-input span.fileinput-exists`).hide();
            $(`#image-input a.fileinput-exists`).hide();
        }
    };

    $scope.onEnviarMensagemTemplate = () => {
        if ($scope.previaTemplate && $scope.previaTemplate.templateType === 'INTERACTIVE') {
            $scope.enviarMensagemInterativa($scope.previaTemplate);
            return;
        }

        $scope.novaMensagem.template = angular.copy($scope.previaTemplate);

        let error = false;

        $scope.novaMensagem.template.components.forEach(component => {
            if (error) { return; }

            if (component.type == 'HEADER') {
                let isMediaHeader = component.format == 'IMAGE'
                    || component.format == 'VIDEO'
                    || component.format == 'DOCUMENT';

                let isHeaderCustomizable = ((component.format == 'TEXT' && $scope.getStringParameters(component.text) > 0) || isMediaHeader);

                if (isHeaderCustomizable && $scope.getComponentParametersCount(component) != 1) {
                    error = true;
                    return swal("Ops!", "Todos os parâmetros do cabeçalho são obrigatórios", "error");
                }
            }

            if (component.type == 'BODY' && $scope.getStringParameters(component.text) > 0 && ($scope.getComponentParametersCount(component) != $scope.getStringParameters(component.text))) {
                error = true;
                return swal("Ops!", "Todos os parâmetros do corpo são obrigatórios", "error");
            }

            if (component.type == 'BUTTONS') {
                component.buttons.forEach(button => {
                    if ((button.type == 'QUICK_REPLY' || (button.type == 'URL' && $scope.getStringParameters(button.url) > 0)) && $scope.getComponentParametersCount(button) != 1) {
                        error = true;
                        return swal("Ops!", "Todos os parâmetros dos botões são obrigatórios", "error");
                    }
                });
            }

            if (component.text) {
                component.text = $scope.renderComponentText(component);
            }
        });

        if (!error) {
            $scope.enviarMensagem('TEMPLATE');
        }
    };

    $scope.getComponentParametersCount = (component) => {
        let count = 0;

        if (component.parameters && component.parameters.length > 0) {
            count = component.parameters.filter(p => p.text).length;
        }

        return count;
    }

    $scope.tratarTexto = function (texto) {
        if (typeof $scope.isEmail == "function" && !$scope.isEmail() && texto) {
            texto = texto.replace(/(https?:\/\/[\w\.:%\+~#=\-\?\/]+)/g, '<a href="$1" target="_blank">$1</a>');
            texto = texto.replace(/(^|\s)\*(\S.*\S)\*(\s|$)/g, '$1<b>$2</b>$3');
        }

        if (texto) {
            texto = texto.replaceAll('\\n', '<br/>');
        }

        if (typeof $scope.isEmail == "function" && $scope.isEmail()) {
            texto = $sce.trustAsHtml($scope.ocultarMensagemCitada(texto));
        }

        return texto;
    }

    //   $scope.blockSpace = function(event) {
    //     if (event.keyCode === 32) {
    //       console.log('Espaço pressionado');
    //     }
    //   };

     $scope.campaignMessage = `Para incluir o nome do contato em qualquer parâmetro, utilize a tag: {{contact.name}}`;
});;

materialAdmin.filter('trustUrl', [
    '$sce',
    function ($sce) {

        return function (url) {

            if (!url) {
                return '';
            }

            return $sce.trustAsResourceUrl(url);

        };

    }
]);
materialAdmin.filter('unique', function () {
    return function (collection, keyname) {

        if (!angular.isArray(collection)) {
            return collection;
        }

        var output = [];
        var seen = {};

        angular.forEach(collection, function (item) {

            if (!item) {
                return;
            }

            var key = keyname ? item[keyname] : item;

            if (key === undefined || key === null) {
                key = item;
            }

            if (!seen[key]) {
                seen[key] = true;
                output.push(item);
            }
        });

        return output;
    };
});

materialAdmin.factory('AtendimentoService', [
    '$http',
    '$window',
    function ($http, $window) {

        var service = {};

        // =====================================================
        // EMPRESA ATUAL
        // =====================================================

        service.getEmpresaId = function () {

            var empresaId = '';

            try {

                // ---------------------------------------------
                // localStorage.empresa
                // ---------------------------------------------

                var empresaStorage =
                    $window.localStorage.getItem('empresa');

                if (empresaStorage) {

                    try {

                        var empresa =
                            JSON.parse(empresaStorage);

                        if (
                            empresa &&
                            typeof empresa === 'object'
                        ) {

                            empresaId =
                                empresa.empresaId ||
                                empresa.empresa_id ||
                                empresa.idEmpresa ||
                                empresa.id ||
                                empresa.codigo ||
                                '';

                        } else {

                            empresaId = empresaStorage;
                        }

                    } catch (erroJson) {

                        // Caso empresa seja uma string:
                        // "LinkFly"

                        empresaId = empresaStorage;
                    }
                }


                // ---------------------------------------------
                // sessionStorage
                // ---------------------------------------------

                if (!empresaId) {

                    empresaId =
                        $window.sessionStorage.getItem(
                            'empresaId'
                        ) ||
                        $window.sessionStorage.getItem(
                            'empresa_id'
                        ) ||
                        $window.sessionStorage.getItem(
                            'idEmpresa'
                        ) ||
                        '';
                }


                // ---------------------------------------------
                // usuario da sessão
                // ---------------------------------------------

                if (!empresaId) {

                    var usuarioStorage =
                        $window.sessionStorage.getItem(
                            'usuario'
                        );

                    if (usuarioStorage) {

                        try {

                            var usuario =
                                JSON.parse(
                                    usuarioStorage
                                );

                            empresaId =
                                usuario.empresaId ||
                                usuario.empresa_id ||
                                usuario.idEmpresa ||
                                usuario.empresa ||
                                '';

                        } catch (erroUsuario) {

                            console.error(
                                'Erro lendo empresa do usuário:',
                                erroUsuario
                            );
                        }
                    }
                }

            } catch (erro) {

                console.error(
                    'Erro obtendo empresaId:',
                    erro
                );
            }

            return String(
                empresaId || ''
            ).trim();
        };


        // =====================================================
        // FUNÇÃO INTERNA PARA LISTAR
        // =====================================================

        service.buscarLista = function (endpoint) {

            var empresaId =
                service.getEmpresaId();

            if (!empresaId) {

                console.error(
                    '❌ AtendimentoService: empresaId não encontrado.'
                );

                return Promise.resolve([]);
            }



            return $http.get(
                endpoint,
                {
                    params: {
                        empresaId: empresaId
                    }
                }
            )
            .then(function (response) {

                var dados =
                    response.data;



                /*
                 * Backend pode retornar:
                 *
                 * [
                 *     {...},
                 *     {...}
                 * ]
                 *
                 * ou:
                 *
                 * {
                 *     atendimentos: [...]
                 * }
                 */

                if (angular.isArray(dados)) {
                    return dados;
                }

                if (
                    dados &&
                    angular.isArray(
                        dados.atendimentos
                    )
                ) {
                    return dados.atendimentos;
                }

                if (
                    dados &&
                    angular.isArray(
                        dados.data
                    )
                ) {
                    return dados.data;
                }

                return [];

            })
            .catch(function (erro) {

                console.error(
                    '❌ Erro carregando:',
                    endpoint,
                    erro
                );

                return [];
            });
        };


        // =====================================================
        // ATIVOS
        // =====================================================

        service.ativos = function () {

            return service.buscarLista(
                'https://notification-n001.n3bot.com.br/api/atendimentos/ativos'
            );

        };


        // =====================================================
        // PENDENTES
        // =====================================================

        service.pendentes = function () {

            return service.buscarLista(
                'https://notification-n001.n3bot.com.br/api/atendimentos/pendentes'
            );

        };


        // =====================================================
        // POTENCIAIS
        // =====================================================

        service.potenciais = function () {

            return service.buscarLista(
                'https://notification-n001.n3bot.com.br/api/atendimentos/potenciais'
            );

        };


        // =====================================================
        // NORMALIZAR ATENDIMENTO
        // =====================================================

        service.normalizar = function (atendimento) {

            atendimento =
                atendimento || {};

            return {

                id:
                    atendimento.id ||
                    atendimento.atendimentoId ||
                    atendimento.chatId ||
                    atendimento.numero ||
                    atendimento.from ||
                    null,

                ticket:
                    atendimento.ticket ||
                    atendimento.protocolo ||
                    '',

                nome:
                    atendimento.nome ||
                    atendimento.nomeCliente ||
                    atendimento.clienteNome ||
                    atendimento.pushname ||
                    atendimento.name ||
                    '',

                cpf:
                    atendimento.cpf ||
                    atendimento.documento ||
                    '',

                imagemperfil:
                    atendimento.imagemperfil ||
                    atendimento.imagemPerfil ||
                    atendimento.foto ||
                    atendimento.fotoPerfil ||
                    atendimento.avatar ||
                    atendimento.profilePic ||
                    '',

                numero:
                    atendimento.numero ||
                    atendimento.telefone ||
                    atendimento.whatsapp ||
                    atendimento.from ||
                    atendimento.chatId ||
                    '',

                status:
                    atendimento.status ||
                    '',

                PossivelTroca:
                    atendimento.PossivelTroca !== undefined
                        ? atendimento.PossivelTroca
                        : (
                            atendimento.possivelTroca !== undefined
                                ? atendimento.possivelTroca
                                : false
                        ),

                empresaId:
                    atendimento.empresaId ||
                    service.getEmpresaId(),

                mensagens:
                    angular.isArray(
                        atendimento.mensagens
                    )
                        ? atendimento.mensagens
                        : [],

                ultimaMensagem:
                    atendimento.ultimaMensagem ||
                    atendimento.ultima_mensagem ||
                    '',

                mensagensNaoVisualizadas:
                    Number(
                        atendimento.mensagensNaoVisualizadas ||
                        atendimento.mensagens_nao_visualizadas ||
                        0
                    ),

                timestamp:
                    atendimento.timestamp ||
                    atendimento.updatedAt ||
                    atendimento.updated_at ||
                    0,

                dados:
                    atendimento
            };
        };


        // =====================================================
        // NORMALIZAR LISTA
        // =====================================================

        service.normalizarLista = function (lista) {

            if (!angular.isArray(lista)) {
                return [];
            }

            return lista.map(function (item) {

                return service.normalizar(item);

            });
        };


        // =====================================================
        // ATIVOS NORMALIZADOS
        // =====================================================

        service.ativosNormalizados = function () {

            return service.ativos()
                .then(function (lista) {

                    return service.normalizarLista(
                        lista
                    );

                });

        };


        // =====================================================
        // PENDENTES NORMALIZADOS
        // =====================================================

        service.pendentesNormalizados = function () {

            return service.pendentes()
                .then(function (lista) {

                    return service.normalizarLista(
                        lista
                    );

                });

        };


        // =====================================================
        // POTENCIAIS NORMALIZADOS
        // =====================================================

        service.potenciaisNormalizados = function () {

            return service.potenciais()
                .then(function (lista) {

                    return service.normalizarLista(
                        lista
                    );

                });

        };


        return service;

    }
]);


materialAdmin.service("UsuarioService", [
    "$window",
    "$http",
    function (
        $window,
        $http
    ) {

        // ==========================================================
        // USUÁRIO
        // ==========================================================

        this.getUsuario = function () {

            var dados =
                $window.sessionStorage.getItem(
                    "usuario"
                );

            if (!dados) {
                return null;
            }

            try {

                return JSON.parse(dados);

            } catch (e) {

                console.error(
                    "Erro ao ler usuário:",
                    e
                );

                return null;
            }
        };


this.atualizarPerfil = function (data) {
    return $http({
        method: "PUT",
        url: `api/usuarios/${data.id}/perfil?_=${Date.now()}`,
        data: data,
        headers: {
            "Cache-Control": "no-cache",
            "Pragma": "no-cache"
        }
    });
};





this.get = function () {
    var usuario = {};

    try {
        usuario = JSON.parse(
            sessionStorage.getItem('usuario') || '{}'
        );
    } catch (e) {
        usuario = {};
    }

    var id = usuario.id ||
             usuario.usuarioId ||
             usuario.idUsuario;

    if (!id) {
        return $q.reject(
            new Error('O usuário da sessão não possui um ID reconhecido.')
        );
    }

    return $http({
        method: 'GET',
        url: `api/usuarios/perfil`,
        params: {
            id: id,
            _: Date.now()
        },
        cache: false,
        headers: {
            'Cache-Control': 'no-cache'
        }
    });
};



        // ==========================================================
        // ID DO USUÁRIO
        // ==========================================================

        this.getUsuarioId = function () {

            var usuario =
                this.getUsuario();

            if (!usuario) {
                return null;
            }

            return (
                usuario.id ||
                usuario.usuarioId ||
                usuario.codigo ||
                null
            );
        };


        // ==========================================================
        // CHAVE DO HEADER
        // ==========================================================

        this.getChaveHeader = function () {

            var usuarioId =
                this.getUsuarioId();

            if (!usuarioId) {

                console.warn(
                    "Usuário não identificado para controle do header."
                );

                return null;
            }

            return (
                "n3bot_novo_header_" +
                usuarioId
            );
        };


        // ==========================================================
        // PEGAR VERSÃO SALVA
        // ==========================================================

        this.getVersaoHeader = function () {

            var chave =
                this.getChaveHeader();

            if (!chave) {
                return null;
            }

            return $window.localStorage.getItem(
                chave
            );
        };


        // ==========================================================
        // SALVAR VERSÃO
        // ==========================================================

        this.salvarVersaoHeader = function (
            versao
        ) {

            var chave =
                this.getChaveHeader();

            if (!chave) {

                console.error(
                    "Não foi possível identificar o usuário."
                );

                return false;
            }

            $window.localStorage.setItem(
                chave,
                String(versao)
            );

            return true;
        };


        // ==========================================================
        // VERIFICAR SE JÁ ACEITOU
        // ==========================================================

        this.jaAceitouHeader = function (
            versao
        ) {

            var versaoSalva =
                this.getVersaoHeader();

            return (
                versaoSalva ===
                String(versao)
            );
        };


        // ==========================================================
        // BUSCAR MANIFEST DO HEADER
        // ==========================================================

        this.buscarManifestHeader = function () {

            return $http.get(
                "/manifest-header.json?_=" +
                Date.now()
            );
        };


// ==========================================================
// VERIFICAR NOVO HEADER
// ==========================================================

this.verificarNovoHeader = function () {

    var self = this;

    return $http.get(
        "/manifest-header.json?_=" + Date.now()
    )
    .then(function (response) {

        var manifest = response.data;




        if (
            !manifest ||
            !manifest.versao ||
            !manifest.header
        ) {

            console.error(
                "Manifest do header inválido:",
                manifest
            );

            throw new Error(
                "Manifest do header inválido."
            );
        }


        // ==============================================
        // VERSÃO DO SERVIDOR
        // ==============================================

        var versaoAtual =
            String(
                manifest.versao
            );


        // ==============================================
        // VERSÃO SALVA PARA O USUÁRIO
        // ==============================================

        var versaoAceita =
            self.getVersaoHeader();




        // ==============================================
        // COMPARAÇÃO
        // ==============================================

        var jaAceitou =
            versaoAceita !== null &&
            String(versaoAceita) ===
            versaoAtual;





        return {

            manifest:
                manifest,

            versaoAtual:
                versaoAtual,

            versaoAceita:
                versaoAceita,

            jaAceitou:
                jaAceitou,

            temNovoHeader:
                !jaAceitou
        };
    });
};


    }
]);


materialAdmin.config(function ($translateProvider) {
    var languages = [
        { key: "en-US", values: {} },
        { key: "pt-BR", values: {} },
        { key: "es-ES", values: {} },
        { key: "zh-CN", values: {} }
    ];

    Object.keys(translateValues || {}).forEach(function (key) {
    var value = translateValues[key];
        $.each(languages, function (i, language) {
            $.each(key.split(","), function (ii, k) {
                k = k.trim();

                if (value.all) {
                    language.values[k] = value.all;
                } else if (value[language.key]) {
                    language.values[k] = value[language.key];
                } else {
                    console.warn(
                        k + ": incomplete translation for language " +
                        language.key
                    );
                }
            });
        });
    });

    $.each(languages, function (i, language) {
        $translateProvider.translations(
            language.key,
            language.values
        );
    });
});


